window.HADITH_DATA=[{"id":"65050","number":1,"title":"Revelation at the age of forty","section":1,"sectionTitle":"Receiving revelation","slug":"01-revelation-at-the-age-of-forty","ref":"Sahih al-Bukhari 3851","source":"https://hadeethenc.com/en/browse/hadith/65050","primary":"https://sunnah.com/bukhari:3851","ar":"عَنِ ‌ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: أُنْزِلَ عَلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهُوَ ابْنُ أَرْبَعِينَ، فَمَكَثَ بِمَكَّةَ ثَلَاثَ عَشْرَةَ سَنَةً، ثُمَّ أُمِرَ بِالْهِجْرَةِ، فَهَاجَرَ إِلَى الْمَدِينَةِ، فَمَكَثَ بِهَا عَشْرَ سِنِينَ، ثُمَّ تُوُفِّيَ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ.","en":"Ibn ‘Abbās (may Allah be pleased with him) reported: The Messenger of Allah (may Allah’s peace and blessings be upon him) received divine revelation at the age of forty. He spent 13 years in Makkah. Then, he was commanded to immigrate, and he immigrated to Madīnah, where he stayed for 10 years. Then, he (may Allah’s peace and blessings be upon him) passed away.","ur":"ابن عباس رضی اللہ عنہما سے مروی ہے، وہ کہتے ہیں: رسول اللہ ﷺ پر چالیس سال کی عمر میں وحی نازل ہوئی۔ پھر آپ تیرہ سال مکہ مکرمہ میں رہے۔ اس کے بعد آپ کو ہجرت کا حکم ہوا تو آپ نے مدینہ طیبہ کی طرف ہجرت فرمائی اور آپ نے وہاں دس برس قیام فرمایا۔ اس کے بعد آپ ﷺ نے وفات پائی۔","titleAr":"بَدْءُ الْوَحْيِ فِي سِنِّ الْأَرْبَعِينَ","titleUr":"چالیس برس کی عمر میں آغازِ وحی"},{"id":"66304","number":2,"title":"The call after the pause","section":1,"sectionTitle":"Receiving revelation","slug":"02-the-call-after-the-pause","ref":"Sahih al-Bukhari 4","source":"https://hadeethenc.com/en/browse/hadith/66304","primary":"https://sunnah.com/bukhari:4","ar":"عَنْ أبي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ أَنَّ جَابِرَ بْنَ عَبْدِ اللَّهِ الأَنْصَارِيِّ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: وَهُوَ يُحَدِّثُ عَنْ فَتْرَةِ الوَحْيِ، فَقَالَ فِي حَدِيثِهِ: «بَيْنَا أَنَا أَمْشِي إِذْ سَمِعْتُ صَوْتًا مِنَ السَّمَاءِ، فَرَفَعْتُ بَصَرِي، فَإِذَا المَلَكُ الَّذِي جَاءَنِي بِحِرَاءٍ جَالِسٌ عَلَى كُرْسِيٍّ بَيْنَ السَّمَاءِ وَالأَرْضِ، فَرُعِبْتُ مِنْهُ، فَرَجَعْتُ فَقُلْتُ: زَمِّلُونِي، فَأَنْزَلَ اللَّهُ تَعَالَى: {يَا أَيُّهَا المُدَّثِّرُ1 قُمْ فَأَنْذِرْ} [المدثر: 2] إِلَى قَوْلِهِ {وَالرُّجْزَ فَاهْجُرْ} [المدثر: 5]. فَحَمِيَ الوَحْيُ وَتَتَابَعَ».","en":"Abu Salamah ibn ‘Abdur-Rahmān reported that Jābir ibn ‘Abdullah al-Ansāri (may Allah be pleased with him and his father) said: While narrating about the halt in revelation, he said in his Hadīth: \"While I was walking, I heard a voice from the sky. I looked up, and there was the angel who had come to me at Hirā’, sitting on a chair between the heaven and the earth. I was terrified of him, so I returned and said: Cover me! Then Allah Almighty revealed: {O you covered [in your cloak], arise and warn} [Surat al-Muddaththir: 1-2] until His saying: {and shun idol worshiping.} [Surat al-Muddaththir: 5] After that, the revelation became intense and continuous.\"","ur":"ابو سلمہ بن عبد الرحمن سے روایت ہے کہ جابر بن عبد اللہ انصاری رضی اللہ عنہما نے وحی کے توقف کے زمانے کا ذکر کرتے ہوئے اپنی حدیث میں فرمایا: \"میں چل رہا تھا کہ اچانک میں نے آسمان سے ایک آواز سنی، میں نے اپنی نظر اٹھائی تو کیا دیکھتا ہوں کہ وہی فرشتہ جو میرے پاس حرا میں آیا تھا آسمان اور زمین کے درمیان ایک کرسی پر بیٹھا ہوا تھا۔ میں اس سے بہت ڈر گیا، چنانچہ میں واپس آیا اور کہا: مجھے کپڑا اوڑھا دو، تو اللہ تعالیٰ نے یہ آیات نازل فرمائیں: {يَا أَيُّهَا المُدَّثِّرُ1 قُمْ فَأَنْذِرْ} سے لے کر {وَالرُّجْزَ فَاهْجُرْ} تک۔ پھر کثرت سے اور مسلسل وحی آنے لگی۔","titleAr":"الدَّعْوَةُ بَعْدَ فَتْرَةِ الْوَحْيِ","titleUr":"وقفۂ وحی کے بعد دعوت کا حکم"},{"id":"10840","number":3,"title":"The ways revelation came","section":1,"sectionTitle":"Receiving revelation","slug":"03-the-ways-revelation-came","ref":"Sahih al-Bukhari 2","source":"https://hadeethenc.com/en/browse/hadith/10840","primary":"https://sunnah.com/bukhari:2","ar":"عن عائشة أُمِّ المؤمنين رضي الله عنها أنَّ الحارثَ بن هشام رضي الله عنه سأل رسولَ الله صلى الله عليه وسلم فقال: يا رسولَ الله، كيف يأْتِيكَ الوَحْيُ؟ فقال رسول الله صلى الله عليه وسلم : «أحْيانًا يَأْتِيني مِثْلَ صَلْصَلَة الجَرَس، وهو أَشدُّه عليَّ، فيَفْصِمُ عنِّي وقد وَعَيْتُ عنه ما قال، وأحيانًا يتمثَّلُ لي المَلَكُ رَجُلًا فيُكَلِّمُني فأَعِي ما يقول». قالت عائشة رضي الله عنها : ولقد رأيتُه ينزِل عليه الوَحْيُ في اليومِ الشديدِ البرْدِ، فيَفْصِمُ عنه وإنَّ جَبِينَه لَيَتَفَصَّدُ عَرَقًا.","en":"‘Ā'ishah (may Allah be pleased with her) reported: Al-Hārith ibn Hishām (may Allah be pleased with him) asked the Messenger of Allah (may Allah's peace and blessings be upon him): \"O Messenger of Allah, how does the revelation come to you?\" The Messenger of Allah (may Allah's peace and blessings be upon him) said: \"Sometimes it comes to me like the ringing of a bell, and that is the hardest for me. When it leaves me I remember what it has said. And sometimes the angel appears to me in the shape of a man, he talks to me, and I understand what he says.\" ‘Ā'ishah (may Allah be pleased with her) said: \"I saw him when the revelation was descending upon him on a very cold day. When it had left him, his forehead was dripping with sweat.\"","ur":"اُم المومنین عائشہ رضی اللہ عنہا سے روایت ہے وہ کہتی ہیں کہ حارث بن ہشام رضی اللہ عنہ نے نبی ﷺ سے پوچھا اور کہا یا رسول اللہﷺ! آپ پر وحی کیسے آتی ہے؟ تو آپ ﷺ نے فرمایا: کبھی تو ایسے آتی ہے جیسے گھنٹے کی آواز ہو، اور یہ وحی مجھ پر بہت سخت گزرتی ہے، چنانچہ جب فرشتے کی ساری باتیں مجھے یاد ہو جاتی ہیں تو یہ موقوف ہو جاتی ہے، اور کبھی فرشتہ انسان کی شکل میں میرے پاس آتا ہے، چنانچہ وہ مجھ سے بات کرتا ہے تو میں وہ جو کچھ کہتا ہے اُسے یاد کر لیتا ہوں، عائشہ رضی اللہ عنہا بیان کر تی ہیں کہ میں نے رسول اللہ ﷺ کو دیکھا کہ سخت جاڑے کے دن آپ پر وحی اترتی پھر ختم ہو جاتی اور آپ ﷺ کی پیشانی سے پسینہ پھوٹ نکلتا۔","titleAr":"كَيْفَ كَانَ يَأْتِي الْوَحْيُ","titleUr":"وحی آنے کی صورتیں"},{"id":"10841","number":4,"title":"The weight of revelation","section":1,"sectionTitle":"Receiving revelation","slug":"04-the-weight-of-revelation","ref":"Sahih Muslim 2334","source":"https://hadeethenc.com/en/browse/hadith/10841","primary":"https://sunnah.com/muslim:2334","ar":"عن عبادة بن الصامت رضي الله عنه ، قال: «كان نبيُّ اللهِ صلى الله عليه وسلم إذا أُنْزِلَ عليه الوحيُ كُرِبَ لذلك وتَرَبَّدَ وجهُه».","en":"‘Ubādah ibn As-Sāmit (may Allah be pleased with him) reported: When the Messenger of Allah (may Allah's peace and blessings be upon him) received revelation, he felt distressed and the color of his face changed","ur":"عبادہ بن صامت رضی اللہ عنہ سے روایت ہے، وہ کہتے ہیں: ”جب اللہ کے نبی ﷺ پر وحی نازل ہوتی، تو اس کی وجہ سے آپ کو تکلیف پہنچتی اور آپ کے چہرے کا رنگ متغیر ہو جاتا تھا“۔","titleAr":"ثِقَلُ الْوَحْيِ","titleUr":"وحی کی گراں بار ذمہ داری"},{"id":"10843","number":5,"title":"Listening before reciting","section":1,"sectionTitle":"Receiving revelation","slug":"05-listening-before-reciting","ref":"Sahih al-Bukhari 5","source":"https://hadeethenc.com/en/browse/hadith/10843","primary":"https://sunnah.com/bukhari:5","ar":"عن ابن عباس رضي الله عنهما في قوله تعالى: {لا تُحَرِّكْ به لسانَك} [القيامة: 16]، قال: «كان النبيُّ صلى الله عليه وسلم يُعالِجُ مِن التنزيل شِدَّةً، وكان يُحَرِّكُ شَفَتَيْهِ» فقال لي ابنُ عباس: فأنا أُحَرِّكُهما لك كما كان رسولُ الله صلى الله عليه وسلم يُحَرِّكُهما، فقال سعيد: أنا أُحَرِّكُهما كما كان ابنُ عباس يُحَرِّكُهما، فحرَّك شَفَتَيْهِ فأنزل اللهُ -عزَّ وجلَّ-: {لا تُحَرِّكْ به لسانَك لِتَعْجَلَ به إنَّ علينا جَمْعَه وقُرآنَه} [القيامة: 17]، قال: «جَمْعَه في صدرك ثم تقرؤه»، {فإذا قرأناه فاتَّبِعْ قُرآنه} [القيامة: 18] قال: «فاستمِع له وأَنْصِتْ، ثم إنَّ علينا أن تقْرَأه، قال: فكان رسول الله صلى الله عليه وسلم إذا أتاه جبريل عليه السلام استمع، فإذا انطلقَ جبريلُ قرأه النبي صلى الله عليه وسلم كما أقرَأَه».","en":"Ibn ‘Abbās (may Allah be pleased with him) commented about the verse: {Move not your tongue with it, [O Muhammad], to hasten with recitation of the Qur'an} [Sūrat al-Qiyāmah: 16], saying: \"The Prophet (may Allah's peace and blessings be upon him) used to experience hardship while the revelation was being sent down upon him, and he used to move his lips (quickly) with what was being revealed to him.\" Ibn ‘Abbās moved his lips saying: \"I am moving my lips in front of you as the Messenger of Allah (may Allah's peace and blessings be upon him) used to move his.\" Sa‘īd (the sub-narrator) also moved his lips saying: \"I am moving my lips just as I saw Ibn ‘Abbās moving his.\" Ibn ‘Abbās added: \"So Allah revealed the following verses: {Move not your tongue with it, [O Muhammad], to hasten with recitation of the Qur'an. Indeed, upon Us is its collection [in your heart] and [to make possible] its recitation.} [Sūrat al-Qiyāmah: 16-17] which means that Allah will make him (the Prophet) remember the portion of the Qur'an which was revealed to him at that time by heart and recite it. Then the verse that followed these two was: {So when We have recited it [through Jibrīl], then follow its recitation} [Sūrat al-Qiyāmah: 18] It means ''listen to it and be silent. Then, it is (for Allah) to make you recite it.\" Afterwards, the Messenger of Allah (may Allah's peace and blessings be upon him) used to listen to Jibrīl whenever he came to him, and after his departure he used to recite it just as Jibrīl taught him to recite it.\"","ur":"ابن عباس رضی اللہ عنہما سے روايت ہے کہ انہوں نے اللہ تعالیٰ کے فرمان: ﴿لا تُحَرِّكْ به لسانَكَ﴾ (القیامۃ: 16) کی تفسیر میں فرمایا کہ نبی ﷺ نزولِ قرآن کے وقت بہت سختی محسوس فرمایا کرتے تھے اور اپنے ہونٹوں کو ہلاتے تھے۔ مجھے ابن عباس رضی اللہ عنہما نے کہا کہ میں تمہیں ویسے ہی اپنے ہونٹ ہلا کر دکھاتا ہوں جس طرح آپ ﷺ ہلاتے تھے۔ سعید بن جبیر رحمہ اللہ کہتے ہیں کہ میں بھی اپنے ہونٹ ویسے ہی ہلاتا ہوں جیسے ابن عباس رضی اللہ عنہما نے ہلائے۔ یہ کہہ کر انہوں نے اپنے ہونٹ ہلائے۔ پھر یہ آیت نازل ہوئی: ﴿لا تُحَرِّكْ به لسانَك لِتَعْجَلَ به إنَّ علينا جَمْعَه وقُرآنَه﴾ ”اے محمد! قرآن کو جلد جلد یاد کرنے کے لیے اپنی زبان نہ ہلاؤ، اس کا جمع کر دینا اور پڑھا دینا ہمارے ذمہ ہے“۔ (القیامۃ: 17)\nابن عباس رضی اللہ عنہما کہتے ہیں کہ اس سے مراد ہے ”قرآن آپ ﷺ کے دل میں جمع دینا اور پڑھا دینا ہمارے ذمہ ہےں، ﴿فَإِذَا قَرَأْنَاهُ فَاتَّبِعْ قُرْآنَهُ﴾ ”پھر جب ہم پڑھ چکیں تو اس پڑھے ہوئے کی اتباع کرو“ (القیامۃ: 18)\nابن عباس رضی اللہ عنہما فرماتے ہیں: (اس کا مطلب یہ ہے) کہ آپ اس کو خاموشی کے ساتھ سنتے رہیں۔ پھر یقیناً یہ ہماری ذمہ داری ہے کہ آپ اس کو پڑھیں (یعنی اس کو محفوظ کر سکیں)۔ چنانچہ اس کے بعد جب رسول الله ﷺ کے پاس جبرائیل علیہ السلام آتے تو آپ ﷺ اسے (توجہ سے) سنتے۔ جب وہ چلے جاتے تو نبی ﷺ اس (وحی) کو اسی طرح پڑھتے جس طرح جبرائیل علیہ السلام نے اسے پڑھایا ہوتا تھا۔","titleAr":"الِاسْتِمَاعُ قَبْلَ التِّلَاوَةِ","titleUr":"تلاوت سے پہلے توجہ سے سننا"},{"id":"65051","number":6,"title":"Recognizing the surah divisions","section":1,"sectionTitle":"Receiving revelation","slug":"06-recognizing-the-surah-divisions","ref":"Sunan Abi Dawud 788","source":"https://hadeethenc.com/en/browse/hadith/65051","primary":"https://sunnah.com/abudawud:788","ar":"عَنِ ‌ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَليهِ وَسَلَّمَ لا يَعْرِفُ فَصْلَ السُّورةِ حَتَّى تَنْزِلَ عَليْهِ {بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ}.","en":"Ibn ‘Abbās (may Allah be pleased with him) reported: The Prophet (may Allah’s peace and blessings be upon him) did not know where Surahs were to be separated until \"In the name of Allah, the Most Compassionate, the Most Merciful\" was revealed to him.","ur":"ابن عباس رضی اللہ عنہما سے مروی ہے، وہ کہتے ہیں: نبی کریم ﷺ کو ایک سورت ختم ہوکر دوسری سورت شروع ہونے کا علم اس وقت تک نہ ہوتا، جب تک آپ پر «بسم الله الرحمن الرحيم» نہ اترتی۔","titleAr":"مَعْرِفَةُ الْفَصْلِ بَيْنَ السُّوَرِ","titleUr":"سورتوں کی حد بندی کی پہچان"},{"id":"65231","number":7,"title":"Revelation as an enduring sign","section":1,"sectionTitle":"Receiving revelation","slug":"07-revelation-as-an-enduring-sign","ref":"Sahih al-Bukhari 4981","source":"https://hadeethenc.com/en/browse/hadith/65231","primary":"https://sunnah.com/bukhari:4981","ar":"عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «مَا مِنَ الأَنْبِيَاءِ نَبِيٌّ إِلَّا أُعْطِيَ مَا مِثْلهُ آمَنَ عَلَيْهِ البَشَرُ، وَإِنَّمَا كَانَ الَّذِي أُوتِيتُ وَحْيًا أَوْحَاهُ اللَّهُ إِلَيَّ، فَأَرْجُو أَنْ أَكُونَ أَكْثَرَهُمْ تَابِعًا يَوْمَ القِيَامَةِ».","en":"Abu Hurayrah (may Allah be pleased with him) reported: The Prophet (ﷺ) said: \"There was no prophet among the prophets except that he was given miracles through which people believed in him. But what I have been given is a revelation which Allah has revealed to me, and I hope to have the most followers among them on the Day of Judgment.\"","ur":"ابو ہریرہ رضی اللہ عنہ سے روایت ہے، وہ کہتے ہیں کہ اللہ کے نبی ﷺ نے فرمایا: \"ہر نبی کو ایسی نشانیاں دی گئیں جن کی مثل پر لوگ ایمان لائے، اور مجھے جو (معجزہ) دیا گیا ہے وہ وحی ہے جو اللہ نے میری طرف بھیجی ہے، چنانچہ میں امید کرتا ہوں کہ قیامت کے دن میرے پیروکار ان سب سے زیادہ ہوں گے\"۔","titleAr":"الْوَحْيُ آيَةٌ بَاقِيَةٌ","titleUr":"وحی: ہمیشہ باقی رہنے والی نشانی"},{"id":"4217","number":8,"title":"Revelation near the end of his life","section":1,"sectionTitle":"Receiving revelation","slug":"08-revelation-near-the-end-of-his-life","ref":"Sahih al-Bukhari 4982","source":"https://hadeethenc.com/en/browse/hadith/4217","primary":"https://sunnah.com/bukhari:4982","ar":"عن أنس بن مالك رضي الله عنه مرفوعاً: إن الله عز وجل تابع الوحي على رسول الله صلى الله عليه وسلم قبل وفاته حتَّى تُوُفِّيَ أكثر ما كان الوحي.","en":"Anas ibn Mālik (may Allah be pleased with him) reported: Allah, Exalted and Glorified, sent down the Divine Revelation to the Messenger of Allah (may Allah's peace and blessings be upon him) abundantly during the period preceding his death until he died at a time when the revelation had never been more abundant.","ur":"انس بن مالک رضی اللہ عنہ سے روایت ہے وہ فرماتے ہیں کہ اللہ عز و جل رسول اللہ ﷺ کی وفات سے پہلے آپ پر پہ در پہ وحی نازل فرماتا رہا یہاں تک کہ آپ ﷺ کی وفات اس وقت ہوئی جب کثرت کے ساتھ وحی نازل ہو رہی تھی۔","titleAr":"كَثْرَةُ الْوَحْيِ فِي أَوَاخِرِ حَيَاتِهِ ﷺ","titleUr":"حیاتِ نبوی ﷺ کے آخری دور میں کثرتِ وحی"},{"id":"4947","number":9,"title":"Obedience and the path to Paradise","section":2,"sectionTitle":"Following the Messenger","slug":"09-obedience-and-the-path-to-paradise","ref":"Sahih al-Bukhari 7280","source":"https://hadeethenc.com/en/browse/hadith/4947","primary":"https://sunnah.com/bukhari:7280","ar":"عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: «كُلُّ أُمَّتِي يَدْخُلُونَ الْجَنَّةَ إِلَّا مَنْ أَبَى»، قَالُوا: يَا رَسُولَ اللهِ، وَمَنْ يَأْبَى؟ قَالَ: «مَنْ أَطَاعَنِي دَخَلَ الْجَنَّةَ، وَمَنْ عَصَانِي فَقَدْ أَبَى».","en":"Abu Hurayrah (may Allah be pleased with him) reported: The Messenger of Allah (may Allah's peace and blessings be upon him) said: \"Everyone of my Ummah will enter Paradise except those who refuse.\" They said: \"And who would refuse, O Messenger of Allah?\" He said: \"He who obeys me will enter Paradise, and who disobeys me has refused.\"","ur":"ابوھریرہ رضی اللہ عنہ سے روایت ہے کہ اللہ کے رسول ﷺ نے فرمایا: \"میری امت کے سب لوگ جنت میں داخل ہوں کے، ماسوا ان لوگوں کے جنھوں نے انکار کیا۔\" پوچھا گیا کہ اے اللہ کے رسول! انکار کرنے والے کون ہوں گے؟ آپ ﷺ نے فرمایا : \"جس نے میری اطاعت کی، وہ جنت میں داخل ہو گا اور جس  نے میری نافرمانی کی، اس نے انکار کیا۔\"","titleAr":"الطَّاعَةُ وَطَرِيقُ الْجَنَّةِ","titleUr":"اطاعت اور جنت کا راستہ"},{"id":"3272","number":10,"title":"Believing in the Messenger","section":2,"sectionTitle":"Following the Messenger","slug":"10-believing-in-the-messenger","ref":"Sahih Muslim 153","source":"https://hadeethenc.com/en/browse/hadith/3272","primary":"https://sunnah.com/muslim:153","ar":"عَنْ أَبِي هُرَيْرَةَ رضي الله عنه عَنْ رَسُولِ اللهِ صلى الله عليه وسلم أنه قال: «وَالَّذِي نَفْسُ مُحَمَّدٍ بِيَدِهِ لَا يَسْمَعُ بِي أَحَدٌ مِنْ هَذِهِ الْأُمَّةِ يَهُودِيٌّ وَلَا نَصْرَانِيٌّ، ثُمَّ يَمُوتُ وَلَمْ يُؤْمِنْ بِالَّذِي أُرْسِلْتُ بِهِ إِلَّا كَانَ مِنْ أَصْحَابِ النَّارِ».","en":"Abu Hurayrah (may Allah be pleased with him) reported that the Messenger of Allah (may Allah's peace and blessings be upon him) said: \"By the One in Whose Hand Muhammad's soul is, there is nobody of this Ummah (community), whether they be Jewish or Christian, who hears of me and then dies without believing in what I was sent with except that he will be among the people of Hellfire.\"","ur":"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے فرمایا : \"قسم ہے اس ذات کی جس کے ہاتھ میں محمد کی جان ہے! اس امت کا کوئی بھی انسان جو میرے بارے میں سنے، وہ یہودی ہو یا نصرانی اور وہ اس شریعت پر ایمان نہ لائے، جسے دے کر میں بھیجا گیا ہوں اور اسی حالت میں اس کی موت ہو جائے، تو وہ جہنمی ہوگا\"۔","titleAr":"الْإِيمَانُ بِالرَّسُولِ ﷺ","titleUr":"رسول اللہ ﷺ پر ایمان"},{"id":"66529","number":11,"title":"Holding firmly to the Sunnah","section":2,"sectionTitle":"Following the Messenger","slug":"11-holding-firmly-to-the-sunnah","ref":"Sunan Abi Dawud 4607","source":"https://hadeethenc.com/en/browse/hadith/66529","primary":"https://sunnah.com/abudawud:4607","ar":"عَنْ أَبِي نَجِيحٍ العِرْبَاضِ بْنِ سَارِيَةَ رضي الله عنه قَالَ: وَعَظَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَوْعِظَةً وَجِلَتْ مِنْهَا القُلُوبُ، وَذَرَفَتْ مِنْهَا العُيُونُ، فَقُلْنَا: يَا رَسُولَ اللهِ! كَأَنَّهَا مَوْعِظَةُ مُوَدِّعٍ؛ فَأَوْصِنَا، قَالَ: «أُوصِيكُمْ بِتَقْوَى اللَّهِ، وَالسَّمْعِ وَالطَّاعَةِ، وَإِنْ تَأَمَّرَ عَلَيْكُمْ عَبْدٌ، فَإِنَّهُ مَنْ يَعِشْ مِنْكُمْ بَعْدِي فَسَيَرَى اخْتِلَافًا كَثِيرًا، فَعَلَيْكُمْ بِسُنَّتِي وَسُنَّةِ الخُلَفَاءِ الرَّاشِدِينَ المَهْدِيينَ، عَضُّوا عَلَيْهَا بِالنَّوَاجِذِ، وَإِيَّاكُمْ وَمُحْدَثَاتِ الأُمُورِ؛ فَإِنَّ كُلَّ بِدْعَةٍ ضَلَالَةٌ».","en":"Abu Najīh al-‘Irbād ibn Sāriyah (may Allah be pleased with him) reported: The Messenger of Allah (ﷺ) gave us an exhortation at which hearts trembled and eyes shed tears. So we said: O Messenger of Allah, it is as though this is the exhortation of one bidding farewell; so advise us. He said: \"I advise you to fear Allah, and to listen and obey even if a slave is appointed as your leader. Whosoever among you shall live after me will see much discord. So hold fast to my Sunnah and the Sunnah of the Rightly-Guided Caliphs, and cling to them firmly. Beware of new things (in religion) because every religious innovation is a misguidance.\"","ur":"ابو نجیح عرباض بن ساریہ رضی اللہ عنہ سے روایت ہے، وہ کہتے ہيں: (ایک مرتبہ) رسول اللہ ﷺ نے ہمیں ایک موثر وعظ فرمایا جس سے دل کانپ اٹھے اور آنکھیں بھر آئیں۔ ہم  نے کہا: اے اللہ کے رسول ﷺ! یہ وعظ تو گویا کسی الوداع کہنے والے کے وعظ کی طرح ہے۔ لہٰذا آپ ہمیں وصیت فرمائیں۔ رسول اللہ ﷺ نے فرمایا: ”میں تمہیں اللہ سے ڈرنے اور (امیر کی بات) سننے اور ماننے کی وصیت کرتا ہوں، اگرچہ تم پر کوئی حبشی غلام امیر بن جائے۔ (یاد رکھو!)تم میں سے جو میرے بعد زندہ رہے گا وہ یقینا بہت اختلاف دیکھے گا۔ چنانچہ تم میری سنت کو اور ہدایت یافتہ خلفائے راشدین کے طریقے کو لازم پکڑنا، انہیں دانتوں سے خوب جکڑ لینا اور دین میں نئے نئے کام ایجاد کرنے سے بچنا، کیونکہ ہر بدعت گمراہی ہے۔“","titleAr":"التَّمَسُّكُ بِالسُّنَّةِ","titleUr":"سنت کو مضبوطی سے تھامنا"},{"id":"65005","number":12,"title":"The authority of the Prophetic teaching","section":2,"sectionTitle":"Following the Messenger","slug":"12-the-authority-of-the-prophetic-teaching","ref":"Jami at-Tirmidhi 2664","source":"https://hadeethenc.com/en/browse/hadith/65005","primary":"https://sunnah.com/tirmidhi:2664","ar":"عن المقدام بن معدِيْكَرِب رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: «أَلَا هَلْ عَسَى رَجُلٌ يَبْلُغُهُ الْحَدِيثُ عَنِّي وَهُوَ مُتَّكِئٌ عَلَى أَرِيكَتِهِ فَيَقُولُ: بَيْنَنَا وَبَيْنَكُمْ كِتَابُ اللهِ، فَمَا وَجَدْنَا فِيهِ حَلَالًا اسْتَحْلَلْنَاهُ، وَمَا وَجَدْنَا فِيهِ حَرَامًا حَرَّمْنَاهُ، وَإِنَّ مَا حَرَّمَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَمَا حَرَّمَ اللهُ».","en":"Al-Miqdām ibn Ma‘dikarib (may Allah be pleased with him) reported: The Messenger of Allah (may Allah's peace and blessings be upon him) said: \"Lo! Soon a Hadīth from me will be conveyed to a man, while he is reclining on his couch, and he says: ‘Between us and you is Allah’s Book. So, whatever we find in it that is lawful, we consider lawful, and whatever we find in it that is unlawful, we consider unlawful.’ Indeed, whatever the Messenger of Allah made unlawful, it is the same as what Allah made unlawful.\"","ur":"مقداد بن معدیکرب رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"خبردار رہو! قریب ہے کہ کوئی آدمی اپنے آراستہ تخت پر ٹیک لگائے بیٹھا ہو اور اس کے پاس میری حدیث پہنچے تو کہے: ہمارے اور تمہارے درمیان (فیصلے کی چیز) بس اللہ کی کتاب ہے۔ اس میں جو چیز ہم حلال پائیں گے اسی کو حلال سمجھیں گے اور اس میں جو چیز حرام پائیں گے اسی کو ہم حرام جانیں گے۔ یاد رکھو! بلاشک و شبہ رسول اللہ ﷺ نے جو چیز حرام قرار دے دی ہے، وہ ویسے ہی حرام ہے، جیسے کہ اللہ کی حرام کی ہوئی چیز\"۔","titleAr":"حُجِّيَّةُ السُّنَّةِ النَّبَوِيَّةِ","titleUr":"سنتِ نبوی کی شرعی حجیت"},{"id":"4792","number":13,"title":"Deeds must belong to the religion","section":2,"sectionTitle":"Following the Messenger","slug":"13-deeds-must-belong-to-the-religion","ref":"Sahih al-Bukhari 2697","source":"https://hadeethenc.com/en/browse/hadith/4792","primary":"https://sunnah.com/bukhari:2697","ar":"عَنْ عَائِشَةَ رضي الله عنها قَالَتْ: قَالَ رَسُولُ اللهِ صلى الله عليه وسلم: «مَنْ أَحْدَثَ فِي أَمْرِنَا هَذَا مَا لَيْسَ فِيهِ فَهُوَ رَدٌّ» متفق عليه.\nولمسلم: «مَنْ عَمِلَ عَمَلًا لَيْسَ عَلَيْهِ أَمْرُنَا فَهُوَ رَدٌّ».","en":"‘Ā’ishah (may Allah be pleased with her) reported that the Messenger of Allah (may Allah's peace and blessings be upon him) said: \"Whoever introduces into this matter of ours (Islam) something that does not belong to it shall have it rejected.\" [Agreed upon] A narration by Muslim reads: \"Whoever does something that is not in accordance with this matter of ours shall have it rejected.\"","ur":"عائشہ رضی اللہ عنہا سے روایت ہے، وہ کہتی ہیں کہ رسول اللہ ﷺ نے فرمایا : ”جس نے ہمارے اس دین میں کوئی ایسی بات ایجاد کی، جو اس کا حصہ نہیں ہے، تو وہ قابل قبول نہیں ہے“۔ ایک اور روایت میں ہے: ”جس نے کوئی ایسا عمل کیا، جس کے متعلق ہمارا حکم نہیں ہے، تو وہ قابل قبول نہيں ہے“۔","titleAr":"مُوَافَقَةُ الْعَمَلِ لِلدِّينِ","titleUr":"عمل کا دین کے مطابق ہونا"},{"id":"4725","number":14,"title":"Commands within our ability","section":2,"sectionTitle":"Following the Messenger","slug":"14-commands-within-our-ability","ref":"Sahih al-Bukhari 7288","source":"https://hadeethenc.com/en/browse/hadith/4725","primary":"https://sunnah.com/bukhari:7288","ar":"عن أبي هريرة رضي الله عنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: «ما نهيتكم عنه فاجتنبوه، وما أمرتكم به فأْتُوا منه ما استطعتم، فإنما أَهلَكَ الذين من قبلكم كثرةُ مسائلهم واختلافهم على أنبيائهم».","en":"Abu Hurayrah (may Allah be pleased with him) reported that the Prophet (may Allah's peace and blessings be upon him) said: \"Avoid what I have forbidden you from; and do as much as you can, of what I have ordered you. Indeed, those before you were ruined because of their excessive questioning and disagreeing with their prophets.\"","ur":"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے فرمایا: ”میں جس بات سے تمہیں منع کروں اس سے اجتناب کرو اور جس بات کا حکم دوں اسے مقدور بھر سر انجام دو۔ تم سے پہلی امتوں کی ہلاکت کا سبب ان کا بہت زیادہ سوالات کرنا اور ان کی اپنے انبیاء کی مخالفت کرنا بنا تھا“۔","titleAr":"امْتِثَالُ الْأَوَامِرِ بِحَسَبِ الِاسْتِطَاعَةِ","titleUr":"استطاعت کے مطابق احکام کی تعمیل"},{"id":"6078","number":15,"title":"Following a balanced Sunnah","section":2,"sectionTitle":"Following the Messenger","slug":"15-following-a-balanced-sunnah","ref":"Sahih Muslim 1401","source":"https://hadeethenc.com/en/browse/hadith/6078","primary":"https://sunnah.com/muslim:1401","ar":"عَنْ أَنَسٍ رضي الله عنه: أَنَّ نَفَرًا مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ سَأَلُوا أَزْوَاجَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنْ عَمَلِهِ فِي السِّرِّ؟ فَقَالَ بَعْضُهُمْ: لَا أَتَزَوَّجُ النِّسَاءَ، وَقَالَ بَعْضُهُمْ: لَا آكُلُ اللَّحْمَ، وَقَالَ بَعْضُهُمْ: لَا أَنَامُ عَلَى فِرَاشٍ، فَحَمِدَ اللهَ وَأَثْنَى عَلَيْهِ، فَقَالَ: «مَا بَالُ أَقْوَامٍ قَالُوا كَذَا وَكَذَا؟ لَكِنِّي أُصَلِّي وَأَنَامُ، وَأَصُومُ وَأُفْطِرُ، وَأَتَزَوَّجُ النِّسَاءَ، فَمَنْ رَغِبَ عَنْ سُنَّتِي فَلَيْسَ مِنِّي».","en":"Anas (may Allah be pleased with him) reported: A group from among the Prophet's Companions asked the wives of the Prophet (may Allah's peace and blessings be upon him) about his deeds in private. Some of them said: I will not marry women. Others said: I will not eat meat. Some others said: I will not sleep on a bed. So, he praised Allah and commended Him and said: \"What is the matter with those people who said such-and-such? But indeed, I pray and sleep, I fast and break the fast, and I marry women. Whoever turns away from my Sunnah does not belong to me.\"","ur":"انس رضی اللہ عنہ سے روایت ہے، وہ کہتے ہیں: نبی ﷺ کے کچھ صحابہ نے نبی ﷺ کی ازواجِ مطہرات سے نبی ﷺ کی تنہائی کے معمول کے بارے میں پوچھا۔ (آپ ﷺ کی عبادت کا معمول سن کر) ان میں سے کسی نے کہا کہ میں عورتوں سے شادی نہیں کروں گا، کسی نے کہا کہ میں گوشت نہیں کھاؤں گا اور کسی نے کہا کہ میں بستر پر نہیں سوؤں گا۔ (نبی ﷺ تک جب یہ بات پہنچی) تو آپ ﷺ نے اللہ تعالی کے حمد و ثنا کے بعد فرمایا: \"کچھ لوگوں کو کیا ہو گیا ہے کہ انہوں نے اس اس طرح کى باتیں کى ہیں؟ میں تو نماز بھی پڑھتا ہوں اور سوتا بھی ہوں، کبھی روزہ رکھتا ہوں اور کبھی نہیں رکھتا اور میں عورتوں سے شادی بھی کرتا ہوں۔ جس نے میری سنت سے گریز کیا اس کا مجھ سےکوئی تعلق نہیں۔\"","titleAr":"اتِّبَاعُ السُّنَّةِ بِاعْتِدَالٍ","titleUr":"اعتدال کے ساتھ سنت کی پیروی"},{"id":"65121","number":16,"title":"The Prophet knew Allah best","section":2,"sectionTitle":"Following the Messenger","slug":"16-the-prophet-knew-allah-best","ref":"Sahih al-Bukhari 20","source":"https://hadeethenc.com/en/browse/hadith/65121","primary":"https://sunnah.com/bukhari:20","ar":"عَنْ عَائِشَةَ أُمِّ المُؤْمِنينَ رَضِيَ اللهُ عَنْها قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا أَمَرَهُمْ أَمَرَهُمْ مِنَ الأَعْمَالِ بِمَا يُطِيقُونَ، قَالُوا: إِنَّا لَسْنَا كَهَيْئَتِكَ يَا رَسُولَ اللَّهِ، إِنَّ اللَّهَ قَدْ غَفَرَ لَكَ مَا تَقَدَّمَ مِنْ ذَنْبِكَ وَمَا تَأَخَّرَ، فَيَغْضَبُ حَتَّى يُعْرَفَ الغَضَبُ فِي وَجْهِهِ، ثُمَّ يَقُولُ: «إِنَّ أَتْقَاكُمْ وَأَعْلَمَكُمْ بِاللَّهِ أَنَا».","en":"‘Ā’ishah, the Mother of the Believers (may Allah be pleased with her), reported: Whenever the Messenger of Allah (ﷺ) instructed his Companions to do something, he would command them only with what they were able to bear. They said: O Messenger of Allah, we are not like you; Allah has forgiven your past and future sins. He would then become angry until his anger would be visible on his face, and say: \"Indeed, I am the most God-fearing among you and the most knowledgeable of Allah.\"","ur":"امّ المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے، وہ کہتی ہيں: رسول اللہ ﷺ جب انہیں اعمال کا حکم دیتے تو انہی کا حکم دیتے جن کی وہ طاقت رکھتے تھے۔ صحابہ عرض کرتے: ”اے اللہ کے رسول! ہم آپ کی طرح نہیں ہیں، اللہ تعالیٰ نے تو آپ کے اگلے پچھلے سب گناہ معاف فرما دیے ہیں“۔ اس پر آپ ﷺ غضب ناک ہو جاتے یہاں تک کہ غصہ آپ کے چہرۂ مبارک پر نمایاں ہو جاتا، پھر آپ ﷺ فرماتے:  ”یقیناً تم میں سب سے زیادہ اللہ سے ڈرنے والا اور اسے جاننے والا میں ہی ہوں۔“","titleAr":"النَّبِيُّ ﷺ أَعْلَمُ النَّاسِ بِاللَّهِ","titleUr":"نبی ﷺ اللہ کو سب سے زیادہ جانتے تھے"},{"id":"5518","number":17,"title":"Understanding the religion","section":3,"sectionTitle":"Learning and transmission","slug":"17-understanding-the-religion","ref":"Sahih al-Bukhari 71","source":"https://hadeethenc.com/en/browse/hadith/5518","primary":"https://sunnah.com/bukhari:71","ar":"عن معاوية رضي الله عنه قال: سمعت النبي صلى الله عليه وسلم يقول: «مَنْ يُرِدِ اللهُ بِهِ خَيْرًا يُفَقِّهْهُ فِي الدِّينِ، وَإِنَّمَا أَنَا قَاسِمٌ، وَاللهُ يُعْطِي، وَلَنْ تَزَالَ هَذِهِ الْأُمَّةُ قَائِمَةً عَلَى أَمْرِ اللهِ، لَا يَضُرُّهُمْ مَنْ خَالَفَهُمْ، حَتَّى يَأْتِيَ أَمْرُ اللهِ».","en":"Mu‘āwiyah (may Allah be pleased with him) reported: I heard the Prophet (may Allah's peace and blessings be upon him) say: \"When Allah intends good for someone, He grants him the understanding of the religion. Indeed, I am only a distributor, and Allah is the Giver. This Ummah will continue to follow Allah's laws, not being harmed by those who oppose them, until Allah's command comes to pass.\"","ur":"معاویہ رضی اللہ عنہ سے روایت ہے، وہ کہتے ہیں کہ میں نے اللہ کے رسول صلی اللہ علیہ و سلم کو کہتے ہوئے سنا ہے : ”جس کے ساتھ اللہ خیر کا ارادہ کرتا ہے، اسے دین کی سمجھ عطا کر دیتا ہے۔ میں تو بس تقسیم کرنے والا ہوں، دینے والا اللہ ہے۔ یہ امت اللہ کے دین پو قائم رہے گی، اس کی مخالفت کرنے والے اسے نقصان نہیں پہنچا سکیں گے، یہاں تک کہ اللہ کا امر آجائے“۔","titleAr":"التَّفَقُّهُ فِي الدِّينِ","titleUr":"دین کی سمجھ حاصل کرنا"},{"id":"4233","number":18,"title":"Guidance is like life-giving rain","section":3,"sectionTitle":"Learning and transmission","slug":"18-guidance-is-like-life-giving-rain","ref":"Sahih al-Bukhari 79","source":"https://hadeethenc.com/en/browse/hadith/4233","primary":"https://sunnah.com/bukhari:79","ar":"عَنْ أَبِي مُوسَى رَضيَ اللهُ عنه عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: «مَثَلُ مَا بَعَثَنِي اللَّهُ بِهِ مِنَ الهُدَى وَالعِلْمِ كَمَثَلِ الغَيْثِ الكَثِيرِ أَصَابَ أَرْضًا، فَكَانَ مِنْهَا نَقِيَّةٌ، قَبِلَتِ المَاءَ، فَأَنْبَتَتِ الكَلَأَ وَالعُشْبَ الكَثِيرَ، وَكَانَتْ مِنْهَا أَجَادِبُ، أَمْسَكَتِ المَاءَ، فَنَفَعَ اللَّهُ بِهَا النَّاسَ، فَشَرِبُوا وَسَقَوْا وَزَرَعُوا، وَأَصَابَتْ مِنْهَا طَائِفَةً أُخْرَى، إِنَّمَا هِيَ قِيعَانٌ لاَ تُمْسِكُ مَاءً وَلاَ تُنْبِتُ كَلَأً، فَذَلِكَ مَثَلُ مَنْ فَقُهَ فِي دِينِ اللَّهِ وَنَفَعَهُ مَا بَعَثَنِي اللَّهُ بِهِ، فَعَلِمَ وَعَلَّمَ، وَمَثَلُ مَنْ لَمْ يَرْفَعْ بِذَلِكَ رَأْسًا، وَلَمْ يَقْبَلْ هُدَى اللَّهِ الَّذِي أُرْسِلْتُ بِهِ».","en":"Abu Mūsa (may Allah be pleased with him) reported that the Prophet (may Allah's peace and blessings be upon him) said: \"The guidance and knowledge with which Allah has sent me are like abundant rain that fell on some ground. A part of it was good, absorbing the water, so it brought forth abundant herbage and pasture; and there were some bare patches in it that retained the water by which Allah gave benefit to people who drank, watered, and grew plants. But some of it fell on another flat portion that could not retain the water or produce herbage. That is like the one who becomes versed in Allah's religion and receives benefit from the message entrusted to me by Allah, so he knows for himself and teaches others; and it is like the one who does not show regard to that and does not accept Allah's guidance with which I have been sent.\"","ur":"ابو موسی اشعری رضی اللہ عنہ سے روایت ہے کہ نبی ﷺ نے فرمایا: ”اللہ عزوجل نے جس علم و ہدایت کے ساتھ مجھ کو مبعوث کیا ہے اس کی مثال اس بارش کی طرح ہے جو زمین پر برسی، زمین کا کچھ حصہ اچھا تھا جس نے اس پانی کو جذب کر لیا اور اس نے چارہ اور بہت سا سبزہ اگایا اور زمین کا بعض حصہ سخت تھا ، اس نے پانی کو روک لیا جس سے اللہ تعالیٰ نے لوگوں کو نفع دیا ، انہوں نے وہ پانی خود پیا ، جانوروں کو پلایا اور کھیتیاں کیں۔ جب کہ زمین کا بعض حصہ چٹیل میدان تھا ، جس پر بارش ہوئی تو اس نے نہ پانی کو روکا اور نہ کسی قسم کی گھاس اگائی۔ پہلی مثال ان لوگوں کی ہے جنہوں نے اللہ کے دین کو سمجھا اور اس کا فیض پہنچایا اور اللہ تعالیٰ نے جس ہدایت کے ساتھ مجھے مبعوث کیا ہے اس کا علم حاصل کیا اور وہ علم آگے پہنچایا (آنے والی نسلوں تک منتقل کیا) اور دوسری مثال ان لوگوں کی ہے جنہوں نے اس کی طرف سر اٹھاکر نہیں دیکھا اور جس ہدایت کے ساتھ مجھے مبعوث کیا گیا ہے اس کو قبول نہیں کیا“۔","titleAr":"الْهِدَايَةُ كَالْغَيْثِ النَّافِعِ","titleUr":"ہدایت: زندگی بخش بارش کی مانند"},{"id":"6820","number":19,"title":"Conveying what we hear accurately","section":3,"sectionTitle":"Learning and transmission","slug":"19-conveying-what-we-hear-accurately","ref":"Jami at-Tirmidhi 2657","source":"https://hadeethenc.com/en/browse/hadith/6820","primary":"https://sunnah.com/tirmidhi:2657","ar":"عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رضي الله عنه قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: «نَضَّرَ اللَّهُ امْرَأً سَمِعَ مِنَّا شَيْئًا فَبَلَّغَهُ كَمَا سَمِعَ، فَرُبَّ مُبَلِّغٍ أَوْعَى مِنْ سَامِعٍ».","en":"‘Abdullah ibn Mas‘ūd (may Allah be pleased with him) reported: I heard the Prophet (may Allah's peace and blessings be upon him) say: \"May Allah brighten the person who hears something from us and conveys it as he heard it, for perhaps the one to whom it is conveyed is more mindful than the hearer.\"","ur":"عبد اللہ بن مسعود رضی اللہ عنہ سے روایت ہے، وہ کہتے ہیں کہ میں نے اللہ کے نبی صلی اللہ علیہ و سلم کو کہتے ہوئے سنا: ”اللہ اس شخص کو تروتازہ (اور خوش) رکھے، جس نے مجھ سے کوئی بات سنی، پھر اس نے اسے جیسے مجھ سے سنا تھا ہو بہو ویسے ہی دوسروں تک پہنچا دیا، کیونکہ بہت سے لوگ جنہیں بات (حدیث) پہنچائی جائے پہنچانے والے سے کہیں زیادہ بات کو سمجھنے والے ہوتے ہیں“۔","titleAr":"أَمَانَةُ تَبْلِيغِ مَا نَسْمَعُ","titleUr":"سنی ہوئی بات درست طور پر پہنچانا"},{"id":"3686","number":20,"title":"Convey faithfully and avoid falsehood","section":3,"sectionTitle":"Learning and transmission","slug":"20-convey-faithfully-and-avoid-falsehood","ref":"Sahih al-Bukhari 3461","source":"https://hadeethenc.com/en/browse/hadith/3686","primary":"https://sunnah.com/bukhari:3461","ar":"عن عبد الله بن عمرو رضي الله عنهما أن النبي صلى الله عليه وسلم قال: «بَلِّغُوا عَنِّي وَلَوْ آيَةً، وَحَدِّثُوا عَنْ بَنِي إِسْرَائِيلَ وَلَا حَرَجَ، وَمَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنَ النَّارِ».","en":"‘Abdullāh ibn ‘Amr (may Allah be pleased with him) reported: The Prophet (may Allah's peace and blessings be upon him) said: \"Convey from me even if one verse, and narrate from the Children of Israel, and there is no sin in doing that. And whoever intentionally tells a lie about me, let him occupy his seat in Hellfire.\"","ur":"عبداللہ بن عمرو رضی اللہ عنہما سے روایت ہے کہ اللہ کے نبی ﷺ نے فرمایا: ”میری طرف سے لوگوں کو پہنچا دو، اگرچہ ایک آیت ہی ہو۔ بنی اسرائیل سے روایت کرو، ان سے بیان کرنے میں کوئی حرج نہیں ہے۔ جس نے مجھ پر جان بوجھ کر جھوٹ باندھا، وہ اپنا ٹھکانہ جہنم میں بنا لے“۔","titleAr":"التَّبْلِيغُ بِأَمَانَةٍ وَاجْتِنَابُ الْكَذِبِ","titleUr":"امانت کے ساتھ نقل اور جھوٹ سے اجتناب"},{"id":"65043","number":21,"title":"Never attribute a deliberate lie","section":3,"sectionTitle":"Learning and transmission","slug":"21-never-attribute-a-deliberate-lie","ref":"Sahih al-Bukhari 110","source":"https://hadeethenc.com/en/browse/hadith/65043","primary":"https://sunnah.com/bukhari:110","ar":"عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: «مَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنَ النَّارِ».","en":"Abu Hurayrah (may Allah be pleased with him) reported that the Messenger of Allah (may Allah's peace and blessings be upon him) said: \"Whoever tells a lie about me intentionally, let him take his seat in Hellfire.\"","ur":"ابو ہریرہ رضی اللہ عنہ سے روایت ہے، وہ کہتے ہیں کہ اللہ کے رسول ﷺ نے فرمایا: \"جو شخص مجھ پر جان بوجھ کر جھوٹ بولے وہ اپنا ٹھکانہ جہنم میں بنا لے۔\"","titleAr":"التَّحْذِيرُ مِنْ تَعَمُّدِ الْكَذِبِ عَلَى النَّبِيِّ ﷺ","titleUr":"نبی ﷺ کی طرف جان بوجھ کر جھوٹی بات منسوب کرنے سے بچنا"},{"id":"65077","number":22,"title":"Recording the Prophetic teaching","section":3,"sectionTitle":"Learning and transmission","slug":"22-recording-the-prophetic-teaching","ref":"Sunan Abi Dawud 3646","source":"https://hadeethenc.com/en/browse/hadith/65077","primary":"https://sunnah.com/abudawud:3646","ar":"عن عبدِ الله بن عمرو رضي الله عنهما قال: كنتُ أكتبُ كلَّ شيءٍ أسمعُه من رسولِ الله صلَّى الله عليه وسلم أُريدُ حفْظَه، فنهتْني قريشٌ، وقالوا: أتكْتبُ كلَّ شيءٍ تَسمَعُه من رسول الله صلَّى الله عليه وسلم، ورسولُ الله صلَّى الله عليه وسلم بَشَرٌ يتكلَّمُ في الغضَبِ والرِّضا؟ فأمسَكتُ عن الكتاب، فذكرتُ ذلك لرسول الله صلَّى الله عليه وسلم، فأومأ بإصبَعِه إلى فيه، فقال: «اكتُبْ، فوالذي نفسي بيدِه، ما يَخرُجُ منه إلا حقٌّ».","en":"‘Abdullāh ibn ‘Amr (may Allah be pleased with him) reported: I used to write down everything I heard from the Messenger of Allah (may Allah's peace and blessings be upon him) in order to memorize it. The Quraysh prohibited me, saying: \"Do you write down everything that you hear from the Messenger of Allah (may Allah's peace and blessings be upon him) while the Messenger of Allah (may Allah's peace and blessings be upon him) is a human being who speaks in anger and pleasure?\" So, I stopped writing and mentioned that to the Messenger of Allah (may Allah's peace and blessings be upon him). Thereupon, he pointed his finger to his mouth and said: \"Write down; for by the One in Whose Hand my soul is, nothing comes out of it except the truth.\"","ur":"عبداللہ بن عمرو رضی اللہ عنہما سے روایت ہے، وہ کہتے ہیں : اللہ کے رسول صلی اللہ علیہ وسلم سے میں جو کچھ سنتا سب لکھ لیا کرتا تھا، تاکہ ان کو محفوظ رکھا جا سکے۔ لہذا قریش کے کچھ لوگوں نے مجھے اس سے منع کیا اور کہا کہ کیا تم اللہ کے رسول صلی اللہ علیہ و سلم سے سنی ہوئی ہر بات لکھ لیا کرتے ہو، جب کہ اللہ کے رسول صلی اللہ علیہ و سلم انسان ہیں، غصہ اور خوشی دونوں حالتوں میں گفتگو کرتے ہیں؟ لہذا میں نے لکھنا موقوف کردیا اور یہ بات رسول اللہ صلی اللہ علیہ وسلم سے عرض کیا، تو آپ صلی اللہ علیہ وسلم نے اپنی انگلی سے اپنے دہن مبارک کی طرف اشارہ کرتے ہوئے فرمایا : \"لکھا کرو، قسم ہے اس ذات کی جس کے ہاتھ میں میری جان ہے، اس سے سوائے حق کے کچھ اور نہیں نکلتا\"۔","titleAr":"كِتَابَةُ الْهَدْيِ النَّبَوِيِّ","titleUr":"تعلیماتِ نبوی کو قلم بند کرنا"},{"id":"10849","number":23,"title":"Writing and its historical context","section":3,"sectionTitle":"Learning and transmission","slug":"23-writing-and-its-historical-context","ref":"Sahih Muslim 3004","source":"https://hadeethenc.com/en/browse/hadith/10849","primary":"https://sunnah.com/muslim:3004","ar":"عن أبي سعيد الخدري أن رسول الله صلى الله عليه وسلم قال: «لا تكتبوا عني، ومَن كتب عني غيرَ القرآن فَلْيَمْحُه، وحدِّثوا عنِّي ولا حَرَج، ومَن كذب عليَّ -قال همام: أحسِبه قال: مُتعمِّدًا- فَلْيَتَبوَّأ مَقْعَدَه مِن النار».","en":"Abu Sa‘īd al-Khudri reported that the Messenger of Allah (may Allah's peace and blessings be upon him) said: \"Do not write down anything from me, and he who wrote down anything from me except the Qur'an, he should erase it. But, narrate from me, for there is nothing wrong in doing so. Whoever attributes any falsehood to me - Hammām said: I think he also said 'deliberately' - let him occupy his seat in Hellfire.”","ur":"ابو سعيد خدری رضی اللہ عنہ سے روایت ہےکہ رسول اللہ ﷺ نےفرمایا: میری کسی بات کو نہ لکھو۔ جس نے مجھ سے قرآن کےعلاوہ کوئی اور بات لکھی ہے وہ اسے مٹا دے، البتہ میری باتیں روایت کرو، اس میں کوئی حرج نہیں ہے لیکن جو شخص میری طرف كوئی جھوٹی بات منسوب کرے گا -ہمام رحمہ اللہ کہتے ہیں کہ میرے خیال میں انہوں نے ”جان بوجھ کر“ کے الفاظ بھی کہے تھے- وہ اپنا ٹھکانہ جہنم میں بنا لے۔","titleAr":"كِتَابَةُ الْحَدِيثِ وَسِيَاقُهَا التَّارِيخِيُّ","titleUr":"کتابتِ حدیث اور اس کا تاریخی پس منظر"},{"id":"6982","number":24,"title":"Responsibility for doubtful reports","section":3,"sectionTitle":"Learning and transmission","slug":"24-responsibility-for-doubtful-reports","ref":"Sahih Muslim Introduction","source":"https://hadeethenc.com/en/browse/hadith/6982","primary":"https://sunnah.com/muslim/introduction","ar":"عَنْ سَمُرَةَ بْنِ جُنْدَبٍ وَالْمُغِيرَةِ بْنِ شُعْبَةَ رضي الله عنهما قَالَا: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «مَنْ حَدَّثَ عَنِّي بِحَدِيثٍ يُرَى أَنَّهُ كَذِبٌ، فَهُوَ أَحَدُ الْكَاذِبِينَ».","en":"Samurah ibn Jundab and Al-Mughīrah ibn Shu‘bah (may Allah be pleased with both of them) reported: The Messenger of Allah (may Allah's peace and blessings be upon him) said: \"Whoever reports a Hadīth on my authority that is thought to be false is one of the two liars.\"","ur":"سمرہ بن جندب اور مغیرہ بن شعبہ رضی اللہ عنہما سے روایت ہے، دونوں کہتے ہیں کہ اللہ کے رسول صلی اللہ علیہ و سلم  نے فرمایا : \"جس نے میری طرف منسوب کر کے کوئی حدیث بیان کی، حالاں کہ اسے لگ رہا ہو کہ وہ جھوٹ ہے، تو وہ بھی جھوٹوں میں سے ہو گا۔\"","titleAr":"الْمَسْؤُولِيَّةُ فِي نَقْلِ الْأَخْبَارِ الْمَشْكُوكِ فِيهَا","titleUr":"مشتبہ روایات نقل کرنے کی ذمہ داری"},{"id":"5913","number":25,"title":"Learn the Quran and teach it","section":4,"sectionTitle":"Living by the Quran","slug":"25-learn-the-quran-and-teach-it","ref":"Sahih al-Bukhari 5027","source":"https://hadeethenc.com/en/browse/hadith/5913","primary":"https://sunnah.com/bukhari:5027","ar":"عن عثمان رضي الله عنه عن النبي صلى الله عليه وسلم قال: «خَيْرُكُمْ مَنْ تَعَلَّمَ الْقُرْآنَ وَعَلَّمَهُ».","en":"‘Uthmān ibn ‘Affān (may Allah be pleased with him) reported: The Prophet (may Allah’s peace and blessings be upon him) said: \"The best of you are those who learn the Qur’an and teach it.\"","ur":"عثمان رضی اللہ عنہ سے روایت ہے کہ اللہ کے نبی صلی اللہ علیہ و سلم نے فرمایا : ”تم میں سب سے بہتر شخص وہ ہے جو قرآن سیکھے اور اسے سکھائے“۔","titleAr":"تَعَلُّمُ الْقُرْآنِ وَتَعْلِيمُهُ","titleUr":"قرآن سیکھنا اور سکھانا"},{"id":"10113","number":26,"title":"The diligent and the struggling reader","section":4,"sectionTitle":"Living by the Quran","slug":"26-the-diligent-and-the-struggling-reader","ref":"Sahih Muslim 798","source":"https://hadeethenc.com/en/browse/hadith/10113","primary":"https://sunnah.com/muslim:798","ar":"عَنْ عَائِشَةَ رضي الله عنها قَالَتْ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «الْمَاهِرُ بِالْقُرْآنِ مَعَ السَّفَرَةِ الْكِرَامِ الْبَرَرَةِ، وَالَّذِي يَقْرَأُ الْقُرْآنَ وَيَتَتَعْتَعُ فِيهِ، وَهُوَ عَلَيْهِ شَاقٌّ، لَهُ أَجْرَانِ».","en":"‘Ā’ishah (may Allah be pleased with her) reported: The Messenger of Allah (may Allah's peace and blessings be upon him) said: \"The proficient reciter of the Qur’an will be with the noble and obedient angel-scribes, and the one who recites the Qur’an stutteringly and finds it difficult will have two rewards.\"","ur":"اُم المومنین عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ ﷺ نے فرمایا: ”جو شخص قرآن کے پڑھنے میں ماہر ہو، وہ معزز اور نیک سفراء (فرشتوں) کے ساتھ ہو گا، اور جو شخص قرآن کو اٹک اٹک کر پڑھتا ہو اور اسے پڑھنے میں مشقت ہوتی ہو تو اس کو دو گنا ثواب ملتا ہے“۔","titleAr":"الْمَاهِرُ بِالْقُرْآنِ وَمَنْ يَتَتَعْتَعُ فِيهِ","titleUr":"ماہر قاری اور مشقت سے پڑھنے والا"},{"id":"5907","number":27,"title":"Keep returning to the Quran","section":4,"sectionTitle":"Living by the Quran","slug":"27-keep-returning-to-the-quran","ref":"Sahih Muslim 791","source":"https://hadeethenc.com/en/browse/hadith/5907","primary":"https://sunnah.com/muslim:791","ar":"عن أبي موسى الأشعري رضي الله عنه عن النبي صلى الله عليه وسلم قال: «تَعَاهَدُوا هَذَا الْقُرْآنَ، فَوَالَّذِي نَفْسُ مُحَمَّدٍ بِيَدِهِ لَهُوَ أَشَدُّ تَفَلُّتًا مِنَ الْإِبِلِ فِي عُقُلِهَا».","en":"Abu Mūsa al-Ash‘ari (may Allah be pleased with him) reported: The Prophet (may Allah’s peace and blessings be upon him) said: \"Keep on reciting this Qur'an, for by the One in Whose Hand my soul is, the Qur'an slips away from memory faster than camels escaping their tying ropes.\"","ur":"ابو موسی اشعری رضی اللہ عنہ سے روایت ہے کہ اللہ کے نبی صلی اللہ علیہ نے فرمایا : ”اس قرآن کی حفاظت (دیکھ بھال) کرو اور اس كى برابر تلاوت كيا كرو۔ قسم ہے اس ذات کی جس کے ہاتھ میں محمد کی جان ہے، یہ قرآن لوگوں کے سینوں سے نکل جانے میں اس اونٹ سے زیادہ تیز ہے جو رسی میں بندھا ہوا ہو“۔","titleAr":"تَعَاهُدُ الْقُرْآنِ","titleUr":"قرآن کو مسلسل دہراتے رہنا"},{"id":"3772","number":28,"title":"Wisdom that is practised and taught","section":4,"sectionTitle":"Living by the Quran","slug":"28-wisdom-that-is-practised-and-taught","ref":"Sahih al-Bukhari 73","source":"https://hadeethenc.com/en/browse/hadith/3772","primary":"https://sunnah.com/bukhari:73","ar":"عن ابن مسعود رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «لا حَسَدَ إلا في اثنتين: رجل آتاه الله مالا، فسَلَّطَه على هَلَكَتِهِ في الحَقِّ، ورجل آتاه الله حِكْمَة، فهو يقضي بها ويُعَلِّمَها».\nوعن ابن عمر رضي الله عنهما ، عن النبي صلى الله عليه وسلم قال: «لا حسد إلا في اثنتين: رجل آتاه الله القرآن، فهو يقوم به آناء الليل وآناء النهار، ورجل آتاه الله مالا، فهو ينفقه آناء الليل وآناء النهار».","en":"Ibn Mas‘ūd (may Allah be pleased with him) reported that the Prophet (may Allah's peace and blessings be upon him) said: \"There should be no envy except in two (cases): A man whom Allah has given wealth and he spends it in the right way, and a man whom Allah has given wisdom and he judges according to it and teaches it to others.\"\n‘Abdullāh ibn ‘Umar (may Allah be pleased with him) reported that the Prophet (may Allah's peace and blessings be upon him) said: \"There should be no envy except in two (cases): a man whom Allah has given (knowledge of) the Qur'an, and he recites it during the night and day, and a man whom Allah has given wealth, and he spends it during the night and day (in a rightful way).”","ur":"ابن مسعود رضي الله عنہ سے روایت ہے کہ رسول اللہ ﷺ نے فرمایا : ”حسد صرف دو صورتوں میں جائز ہے۔ ایک تو یہ کہ کسی شخص کو اللہ نے دولت دی ہو اور وہ اسے اس کو راہ حق میں خرچ کرنے پر لگا دیا ہو اور دوسرا یہ کہ کسی شخص کو اللہ نے حکمت ( کی دولت) سے نوازا ہو اور وہ اس کے ساتھ فیصلہ کرتا ہو اور ( لوگوں کو) اس حکمت کی تعلیم دیتا ہو“۔\nابن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ ﷺ نے فرمایا: ”حسد صرف دو صورتوں میں جائز ہے؛ ایک تو یہ کہ کسی آدمی کو اللہ تعالی قرآن سے نوازے اور وہ دن رات اس (کی تلاوت اور تعلیم و تدریس) میں لگا رہے اور دوسرا وہ شخص جس کو اللہ مال عطا کرے اور وہ دن رات اسے (وجوہ خیر میں) خرچ کرتا رہے“۔","titleAr":"الْحِكْمَةُ بَيْنَ الْعَمَلِ وَالتَّعْلِيمِ","titleUr":"حکمت پر عمل اور اس کی تعلیم"},{"id":"65285","number":29,"title":"We hear and we obey","section":4,"sectionTitle":"Living by the Quran","slug":"29-we-hear-and-we-obey","ref":"Sahih Muslim 125","source":"https://hadeethenc.com/en/browse/hadith/65285","primary":"https://sunnah.com/muslim:125","ar":"عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: لَمَّا نَزَلَتْ عَلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ {لِلَّهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَإِنْ تُبْدُوا مَا فِي أَنْفُسِكُمْ أَوْ تُخْفُوهُ يُحَاسِبْكُمْ بِهِ اللهُ فَيَغْفِرُ لِمَنْ يَشَاءُ وَيُعَذِّبُ مَنْ يَشَاءُ وَاللهُ عَلَى كُلِّ شَيْءٍ قَدِيرٌ} [البقرة: 284]، قَالَ: فَاشْتَدَّ ذَلِكَ عَلَى أَصْحَابِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَأَتَوْا رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ثُمَّ بَرَكُوا عَلَى الرُّكَبِ، فَقَالُوا: أَيْ رَسُولَ اللهِ، كُلِّفْنَا مِنَ الأَعْمَالِ مَا نُطِيقُ، الصَّلَاةَ وَالصِّيَامَ وَالجِهَادَ وَالصَّدَقَةَ، وَقَدِ اُنْزِلَتْ عَلَيْكَ هَذِهِ الآيَةُ وَلَا نُطِيقُهَا، قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «أَتُرِيدُونَ أَنْ تَقُولُوا كَمَا قَالَ أَهْلُ الكِتَابَيْنِ مِنْ قَبْلِكُمْ سَمِعْنَا وَعَصَيْنَا؟ بَلْ قُولُوا: سَمِعْنَا وَأَطَعْنَا غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ المَصِيرُ»، قَالُوا: سَمِعْنَا وَأَطَعْنَا غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ المَصِيرُ، فَلَمَّا اقْتَرَأَهَا القَوْمُ، ذَلَّتْ بِهَا أَلْسِنَتُهُمْ، فَأَنْزَلَ اللهُ فِي إِثْرِهَا: {آمَنَ الرَّسُولُ بِمَا أُنْزِلَ إِلَيْهِ مِنْ رَبِّهِ وَالمُؤْمِنُونَ كُلٌّ آمَنَ بِاللهِ وَمَلَائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِنْ رُسُلِهِ وَقَالُوا سَمِعْنَا وَأَطَعْنَا غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ المَصِيرُ} [البقرة: 285]، فَلَمَّا فَعَلُوا ذَلِكَ نَسَخَهَا اللهُ تَعَالَى، فَأَنْزَلَ اللهُ عَزَّ وَجَلَّ: {لَا يُكَلِّفُ اللهُ نَفْسًا إِلَّا وُسْعَهَا لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا اكْتَسَبَتْ رَبَّنَا لَا تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا} [البقرة: 286] \" قَالَ: «نَعَمْ» {رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَا إِصْرًا كَمَا حَمَلْتَهُ عَلَى الَّذِينَ مِنْ قَبْلِنَا} [البقرة: 286] قَالَ: «نَعَمْ» {رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِ} [البقرة: 286] قَالَ: «نَعَمْ» {وَاعْفُ عَنَّا وَاغْفِرْ لَنَا وَارْحَمْنَا أَنْتَ مَوْلَانَا فَانْصُرْنَا عَلَى الْقَوْمِ الكَافِرِينَ} [البقرة: 286] قَالَ: «نَعَمْ».","en":"Abu Hurayrah (may Allah be pleased with him) reported: When the verse: {To Allah belongs all that is in the heavens and all that is on earth. Whether you reveal what is within yourselves or conceal it, Allah will call you to account for it. He forgives whom He wills and punishes whom He wills, for Allah is Most Capable of all things} [Surat al-Baqarah: 284] was revealed to the Messenger of Allah (ﷺ), he said: It was very hard on the Companions of the Messenger of Allah (ﷺ). They came to the Messenger of Allah (ﷺ), knelt down on their knees, and said:\nO Messenger of Allah, we have been commanded to do acts of worship we can bear—prayer, fasting, Jihad, and charity—but now this verse has been revealed to you, and we cannot endure it. The Messenger of Allah (ﷺ) said: \"Do you wish to say as the People of the Two Scriptures said before you: We hear and we disobey?Rather say: We hear and obey. Grant us Your forgiveness, our Lord, and to You is the [final] destination.\" So they said: We hear and obey. Grant us Your forgiveness, our Lord, and to You is the final destination. When they recited it and their tongues humbly uttered those words, Allah revealed thereafter: {The Messenger believes in what has been sent down to him from his Lord, as do the believers. All of them believe in Allah, His angels, His Books, and His messengers, [saying], “We make no distinction between any of His messengers.” And they say, “We hear and obey. Grant us Your forgiveness, our Lord, and to You is the [final] destination.”} [Surat al-Baqarah: 285] Then Allah Almighty, out of His mercy, abrogated the previous ruling and revealed: {Allah does not burden any soul greater than it can bear. For it is what it has earned, and against it is what it has incurred. Our Lord, do not hold us accountable if we forget or fall into error.} [Surat al-Baqarah: 286] He said: \"Yes.\" {Our Lord, do not place on us such a burden as You have placed on those before us.} [Surat al-Baqarah: 286] He said: \"Yes.\" {Our Lord, do not burden us with that which we cannot bear.} [Surat al-Baqarah: 286] He said: \"Yes.\" {Pardon us, forgive us, and have mercy on us. You are our Protector, so give us victory over the disbelieving people.} [Surat al-Baqarah: 286] He said: \"Yes.\"","ur":"ابو ہریرہ رضی اللہ عنہ سے روایت ہے، وہ کہتے ہيں: جب رسول اللہ ﷺ پر یہ آیت نازل ہوئی: ’’آسمانوں اور زمین کی ہر چیز اللہ تعالی ہی کی ملکیت ہے‘ تمہارے دلوں میں جو کچھ ہے اسے تم ظاہر کرو یا چھپاؤ‘ اللہ تعالی اس کا حساب تم سے لے گا۔ پھر جسے چاہے بخشے اور جسے چاہے سزا دے اور اللہ تعالی ہر چیز پر قادر ہے‘‘ [البقرة: 284]، تو یہ آیت صحابۂ کرام رضی اللہ عنہم پر بڑی گراں گزری۔ وہ رسول اللہ ﷺ کے پاس آئے، پھر گھٹنوں کے بل بیٹھ گئے اور کہا: اے اللہ کے رسول! ہمیں ان اعمال کا مکلف کیا گیا جن کی ہم طاقت رکھتے ہیں، (جیسے) نماز، روزہ، جہاد اور صدقہ۔ اور (اب) آپ پر یہ آیت نازل ہوئی ہے، یہ ہماری طاقت سے باہر ہے۔ رسول اللہ ﷺ نے فرمایا: «کیا تم وہی کہنا چاہتے ہو جو تم سے پہلے دونوں اہل کتاب نے کہا تھا کہ ہم نے سنا اور نافرمانی کی؟  بلکہ تم کہو: ہم نے سنا اور اطاعت کی۔ اے ہمارے رب! ہم تجھ سے بخشش مانگتے ہیں اور تیری ہی طرف پھرنا ہے»۔ انھوں نے کہا: ہم نے سنا اور اطاعت کی۔ اے ہمارے رب! ہم تجھ سے بخشش مانگتے ہیں اور تیری ہی طرف پھرنا ہے۔ جب لوگوں نے (یہ کلمات) پڑھے اور ان کے ساتھ ان کی زبانیں رواں ہو گئیں تو اللہ نے اس کے بعد یہ آیت نازل فرمائی: ’’رسول ایمان لایا اس چیز پر جو اس کی طرف اللہ تعالی کی جانب سے اتری اور مومن بھی ایمان لائے‘ یہ سب اللہ تعالی اور اس کے فرشتوں پر اور اس کی کتابوں پر اور اس کے رسولوں پر ایمان لائے‘ اس کے رسولوں میں سے سے کسی میں ہم تفریق نہیں کرتے‘ انہوں نے کہہ دیا کہ ہم نے سنا اور اطاعت کی‘ ہم تیری بخشش طلب کرتے ہیں اے ہمارے رب! اور ہمیں تیری ہی طرف لوٹنا ہے۔‘‘ [البقرة: 285]۔ جب انھوں نے ایسا کر لیا تو اللہ تعالی نے اسے منسوخ فرما دیا اور اللہ عز و جل نے یہ نازل فرمایا: ’’اللہ تعالی کسی جان کو اس کی طاقت سے زیادہ تکلیف نہیں دیتا‘ جو نیکی وہ کرے وہ اس کے لیے اور جو برائی وہ کرے وہ اس پر ہے‘ اے ہمارے رب! اگر ہم بھول گئے ہوں یا خطا کی ہو تو ہمیں نہ پکڑنا۔‘‘ [البقرة: 286] اللہ تعالی نے فرمایا: ’’ہاں۔‘‘ (پھر کہا:) ’’اے ہمارے رب! ہم پر اس طرح بوجھ نہ ڈالنا جس طرح تو نے ہم سے پہلے لوگوں پر ڈالا تھا۔‘‘ [البقرة: 286] اللہ تعالی نے فرمایا: ’’ہاں۔‘‘ (پھر کہا:) ’’اے ہمارے رب! ہم پر وہ بوجھ نہ ڈال جس کی ہمیں طاقت نہ ہو۔‘‘ [البقرة: 286] اللہ تعالی نے فرمایا: ’’ہاں۔‘‘ (پھر کہا:) ’’اور ہمیں بخش دے اور ہم پر رحم کر! تو ہی ہمارا مالک ہے‘ ہمیں کافروں کی قوم پر غلبہ عطا فرما۔‘‘ [البقرة: 286] اللہ تعالی نے فرمایا: ’’ہاں۔‘‘","titleAr":"سَمِعْنَا وَأَطَعْنَا","titleUr":"ہم نے سنا اور اطاعت کی"},{"id":"10851","number":30,"title":"The Quran as an intercessor","section":4,"sectionTitle":"Living by the Quran","slug":"30-the-quran-as-an-intercessor","ref":"Sahih Muslim 804","source":"https://hadeethenc.com/en/browse/hadith/10851","primary":"https://sunnah.com/muslim:804","ar":"عن أبي أمامة الباهلي رضي الله عنه قال: سمعتُ رسول الله صلى الله عليه وسلم يقول: «اقرؤوا القرآنَ فإنَّه يأتي يوم القيامة شَفِيعًا لأصحابه، اقرؤوا الزَّهرَاوَين البقرةَ وسورةَ آل عِمران، فإنهما تأتِيان يوم القيامة كأنهما غَمَامَتان، أو كأنهما غَيَايَتانِ، أو كأنهما فِرْقانِ من طَيْر صَوافٍّ، تُحاجَّان عن أصحابهما، اقرؤوا سورة البقرة، فإن أخذها بَرَكة، وتركها حَسْرة، ولا تستطيعها البَطَلَة».","en":"Abu ’Umāmah al-Bāhili (may Allah be pleased with him) reported: I heard the Messenger of Allah (may Allah's peace and blessings be upon him) say: \"Recite the Qur’an, for on the Day of Judgment it will come as an intercessor for those who recite it. Recite Az-Zahrāwayn (the two bright ones), Al-Baqarah, and Āl ‘Imrān, for on the Day of Judgment, they will come as two clouds or two shades, or two flocks of birds in ranks, pleading for those who recite them. Recite Surat al-Baqarah, for taking recourse to it is a blessing and abandoning it is a cause of grief, and magicians cannot confront it.\"","ur":"ابو امامہ باہلی رضی اللہ تعالیٰ عنہ سے روایت ہے، انہوں نے کہا کہ میں نے رسول اللہ ﷺ کو یہ فرماتے ہوئے سنا: ”قرآن پڑھا کرو کیونکہ وہ قیامت کے دن اپنے پڑھنے والوں کا سفارشی بن کر آئےگا۔ دو روشن چمکتی ہوئی سورتیں:البقرہ اور آل عمران پڑھا کرو کیونکہ وہ قیامت کے دن اس طرح آئیں گی جیسے وہ دو بادل یا دو سائبان ہوں یا دو اڑتے ہوئے پرندوں کی قطاریں ہوں اور وہ اپنے پڑھنے والوں کی طرف سے حجت (دفاع) کریں گی۔ سورہ بقرہ پڑھا کرو کیونکہ اسے حاصل کرنا باعث برکت ہے اور اس کا ترک کرنا باعثِ حسرت ہے اور باطل پرست اس کی طاقت نہیں رکھتے“۔","titleAr":"شَفَاعَةُ الْقُرْآنِ","titleUr":"قرآن کی شفاعت"},{"id":"10119","number":31,"title":"Being elevated through the Book","section":4,"sectionTitle":"Living by the Quran","slug":"31-being-elevated-through-the-book","ref":"Sahih Muslim 817","source":"https://hadeethenc.com/en/browse/hadith/10119","primary":"https://sunnah.com/muslim:817","ar":"عن عمر بن الخطاب رضي الله عنه : أن النبي صلى الله عليه وسلم قال: «إن اللهَ يَرفعُ بهذا الكِتابِ أقْواماً ويَضَعُ به آخَرِينَ».","en":"‘Umar ibn al-Khattāb (may Allah be pleased with him) reported that the Prophet (may Allah's peace and blessings be upon him) said: “Indeed, Allah elevates some people with this Book and degrades others.”","ur":"عمر بن خطاب رضی اللہ عنہ سے روایت ہے کہ نبی کریم ﷺ نے فرمایا: ”اللہ تعالیٰ اس کتاب کے ذریعے بہت سے لوگوں کو بلند کرتا ہے اور اسی کتاب کے ذریعے بہت سے لوگوں کو پست و ذلیل کرتا ہے۔“","titleAr":"الرِّفْعَةُ بِالْقُرْآنِ","titleUr":"قرآن کے ذریعے بلندی"},{"id":"65059","number":32,"title":"Recognizing the greatest verse","section":4,"sectionTitle":"Living by the Quran","slug":"32-recognizing-the-greatest-verse","ref":"Sahih Muslim 810","source":"https://hadeethenc.com/en/browse/hadith/65059","primary":"https://sunnah.com/muslim:810","ar":"عَنْ ‌أُبَيِّ بْنِ كَعْبٍ رضي الله عنه قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «يَا أَبَا الْمُنْذِرِ، أَتَدْرِي أَيُّ آيَةٍ مِنْ كِتَابِ اللهِ مَعَكَ أَعْظَمُ؟» قَالَ: قُلْتُ: اللهُ وَرَسُولُهُ أَعْلَمُ. قَالَ: «يَا أَبَا الْمُنْذِرِ، أَتَدْرِي أَيُّ آيَةٍ مِنْ كِتَابِ اللهِ مَعَكَ أَعْظَمُ؟» قَالَ: قُلْتُ: {اللهُ لا إِلَهَ إِلا هُوَ الْحَيُّ الْقَيُّومُ} [البقرة: 255]. قَالَ: فَضَرَبَ فِي صَدْرِي، وَقَالَ: «وَاللهِ لِيَهْنِكَ الْعِلْمُ، أَبَا الْمُنْذِرِ».","en":"Ubayy ibn Ka‘b (may Allah be pleased with him) reported: The Messenger of Allah (may Allah’s peace and blessings be upon him) said: \"O Abu al-Mundhir, do you know which verse of Allah's Book that you have is the greatest?\" I replied: \"Allah and His Messenger know best.\" He said: \"O Abu al-Mundhir, do you know which verse of Allah's Book that you have is the greatest?\" I said: \"{Allah: none has the right to be worshiped except Him, the Ever-Living, All-Sustaining...} [Surat al-Baqarah: 255].\" Thereupon, he struck me on the chest and said: \"May knowledge be pleasant for you, O Abu al-Mundhir!\"","ur":"ابی بن کعب رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اے ابو منذر! کیا تم جانتے ہو کہ تمھارے پاس موجود اللہ کی کتاب کی کون سی آیت سب سے عظیم ہے؟۔‘‘ ان کا کہنا ہے کہ میں نے عرض کیا: اللہ اوراس کے رسول ﷺ زیادہ جانتے ہیں۔ آپﷺ نے (دوبارہ) فرمایا: ’’اے ابو منذر! کیا تم جانتے ہو کہ تمھارے پاس موجود اللہ کی کتاب کی کون سی آیت سب سے عظیم ہے؟۔‘‘ ان کا کہنا ہے کہ میں نے عرض کیا: ﴿اللَّهُ لَا إِلہ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ﴾ ان کا کہنا ہے کہ یہ سننے کے بعد آپﷺ نے میرے سینے پر ہاتھ مارا اور فرمایا: ’’اللہ کی قسم ! ابو منذر! تمھیں یہ علم مبارک ہو\"۔","titleAr":"مَعْرِفَةُ أَعْظَمِ آيَةٍ","titleUr":"عظیم ترین آیت کی پہچان"},{"id":"5795","number":33,"title":"Religion is a path of ease","section":5,"sectionTitle":"A balanced Prophetic path","slug":"33-religion-is-a-path-of-ease","ref":"Sahih al-Bukhari 39","source":"https://hadeethenc.com/en/browse/hadith/5795","primary":"https://sunnah.com/bukhari:39","ar":"عَنْ أَبِي هُرَيْرَةَ رضي الله عنه عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: «إِنَّ الدِّينَ يُسْرٌ، وَلَنْ يُشَادَّ الدِّينَ أَحَدٌ إِلَّا غَلَبَهُ، فَسَدِّدُوا وَقَارِبُوا، وَأَبْشِرُوا، وَاسْتَعِينُوا بِالْغَدْوَةِ وَالرَّوْحَةِ وَشَيْءٍ مِنَ الدُّلْجَةِ».","en":"Abu Hurayrah (may Allah be pleased with him) reported: The Prophet (may Allah's peace and blessings be upon him) said: \"Indeed, the religion is easy. No one overburdens himself in the religion except that he will be overwhelmed by it. So, seek uprightness (be moderate) and try to be close to it and receive the glad tidings. Seek help by worship in the Ghadwah (early morning), Rawhah (afternoon), and part of the Duljah (night).\"","ur":"ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ اللہ کے نبی صلی اللہ علیہ و سلم  نے فرمایا : \"بے شک دین آسان ہے۔ جو شخص دین کے معاملے میں سختی اختیار کرے گا، اس پر دین غالب آ جائے گا۔ چنانچہ اپنے عمل میں راستگی اختیار کرو اور جہاں تک ممکن ہو میانہ روی برتو اور خوش ہو جاؤ، اور صبح و شام اور کسی قدر رات میں (عبادت کے ذریعہ) مدد حاصل کرو\"۔","titleAr":"الدِّينُ يُسْرٌ","titleUr":"دین آسانی کا راستہ ہے"},{"id":"6389","number":34,"title":"Choose ease within lawful limits","section":5,"sectionTitle":"A balanced Prophetic path","slug":"34-choose-ease-within-lawful-limits","ref":"Sahih al-Bukhari 3560","source":"https://hadeethenc.com/en/browse/hadith/6389","primary":"https://sunnah.com/bukhari:3560","ar":"عَنْ عَائِشَةَ أُمِّ المُؤْمِنينَ رَضِيَ اللَّهُ عَنْهَا أَنَّهَا قَالَتْ: مَا خُيِّرَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بَيْنَ أَمْرَيْنِ إِلَّا أَخَذَ أَيْسَرَهُمَا، مَا لَمْ يَكُنْ إِثْمًا، فَإِنْ كَانَ إِثْمًا كَانَ أَبْعَدَ النَّاسِ مِنْهُ، وَمَا انْتَقَمَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِنَفْسِهِ إِلَّا أَنْ تُنْتَهَكَ حُرْمَةُ اللَّهِ، فَيَنْتَقِمَ لِلَّهِ بِهَا.","en":"‘Ā’ishah, Mother of the Believers, (may Allah be pleased with her) reported: The Messenger of Allah (may Allah's peace and blessings be upon him) was never given a choice between two things except that he would choose the easier of the two unless it were a sin. If it were a sin, he would be the farthest of people from it. The Messenger of Allah (may Allah's peace and blessings be upon him) never took revenge for himself, but when the prohibitions of Allah were violated, he would take revenge for the sake of Allah.","ur":"امّ المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے، وہ کہتی ہيں: جب بھی رسول اللہ ﷺ کو دو چیزوں میں سے ایک کا انتخاب کرنا ہوتا، تو آپ ﷺ ہمیشہ دونوں میں سے آسان کا انتخاب کرتے، بشرط کہ وہ آسان کام گناہ نہ ہوتا۔ اگر وہ گناہ ہوتا، تو آپ ﷺ اس سے سب سے زیادہ دور رہتے۔ رسول اللہ ﷺ نے کبھی اپنی ذات کے لیے انتقام نہیں لیا، ما سوا اس کے کہ اللہ کی حرمات میں سے کسی حرمت کو پامال کیا جائے۔ اس صورت میں آپ ﷺ اللہ تعالی کے لیے انتقام لیا کرتے تھے۔","titleAr":"اخْتِيَارُ الْأَيْسَرِ فِي حُدُودِ الشَّرْعِ","titleUr":"شرعی حدود میں آسانی اختیار کرنا"},{"id":"11282","number":35,"title":"Concern for the community","section":5,"sectionTitle":"A balanced Prophetic path","slug":"35-concern-for-the-community","ref":"Sahih al-Bukhari 1128","source":"https://hadeethenc.com/en/browse/hadith/11282","primary":"https://sunnah.com/bukhari:1128","ar":"عن عائشة رضي الله عنها ، قالت: «إنْ كان رسول الله صلى الله عليه وسلم لَيَدَعُ العمل، وهو يُحِبُّ أن يعملَ به خَشْيَة أن يعملَ به الناس، فَيُفْرَضَ عليهم، وما سَبَّح رسول الله صلى الله عليه وسلم سُبْحَة الضُّحى قَطُّ وإنِّي لَأُسَبِّحُهَا».","en":"‘Ā’ishah (may Allah be pleased with her) reported: The Messenger of Allah (may Allah's peace and blessings be upon him) would give up a deed, even though he liked to perform it, for fear that people would follow him and perform it, and it would thus become obligatory for them. The Prophet (may Allah's peace and blessings be upon him) never prayed the Duha prayer, but I offer it.","ur":"عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ رسول اللہ ﷺ کسی کام کو چھوڑ دیتے، حالاں کہ آپ ﷺ کو اس کا کرنا پسند ہوتا، اس خیال سے کہ دوسرے لوگ بھی اس پر (آپ کو دیکھ کر) عمل شروع کر دیں اور اس طرح وہ کام ان پر فرض ہوجائے۔ رسول اللہ ﷺ نے چاشت کی نماز کبھی نہیں پڑھی، لیکن میں پڑھتی ہوں۔","titleAr":"الرِّفْقُ بِالْأُمَّةِ وَالْحِرْصُ عَلَيْهَا","titleUr":"امت کی خیر خواہی اور اس کے لیے آسانی"},{"id":"3373","number":36,"title":"Calling others to guidance","section":5,"sectionTitle":"A balanced Prophetic path","slug":"36-calling-others-to-guidance","ref":"Sahih Muslim 2674","source":"https://hadeethenc.com/en/browse/hadith/3373","primary":"https://sunnah.com/muslim:2674","ar":"عَنْ أَبِي هُرَيْرَةَ رضي الله عنه أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: «مَنْ دَعَا إِلَى هُدًى كَانَ لَهُ مِنَ الْأَجْرِ مِثْلُ أُجُورِ مَنْ تَبِعَهُ، لَا يَنْقُصُ ذَلِكَ مِنْ أُجُورِهِمْ شَيْئًا، وَمَنْ دَعَا إِلَى ضَلَالَةٍ كَانَ عَلَيْهِ مِنَ الْإِثْمِ مِثْلُ آثَامِ مَنْ تَبِعَهُ، لَا يَنْقُصُ ذَلِكَ مِنْ آثَامِهِمْ شَيْئًا».","en":"Abu Hurayrah (may Allah be pleased with him) reported that the Messenger of Allah (may Allah's peace and blessings be upon him) said: \"Whoever calls to guidance shall receive a reward similar to the rewards obtained by those who followed him without diminishing anything from their rewards. And whoever calls to misguidance shall incur a sin similar to the sins incurred by those who followed him without diminishing anything from their sins.\"","ur":"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے فرمایا: \"جس نے کسی ہدایت کی طرف بُلایا، اسے اس کی پیروی کرنے والوں کے اجر کے برابر اجر ملے گا اور اس سے پیروی کرنے والوں کے اجر میں کوئی کمی نہیں ہوگی اور جس نے کسی گمراہی کی طرف بلایا اُس کے اوپر اس کی پیروی کرنے والوں کے برابر گناہ (کا بوجھ) ہوگا اور اس سے ان کے گناہوں میں کوئی کمی نہیں ہوگی۔\"","titleAr":"الدَّعْوَةُ إِلَى الْهُدَى","titleUr":"ہدایت کی طرف بلانا"},{"id":"3506","number":37,"title":"Setting a beneficial example","section":5,"sectionTitle":"A balanced Prophetic path","slug":"37-setting-a-beneficial-example","ref":"Sahih Muslim 1017","source":"https://hadeethenc.com/en/browse/hadith/3506","primary":"https://sunnah.com/muslim:1017","ar":"عن جرير بن عبد الله رضي الله عنه قال: كُنَّا في صَدرِ النَّهَار عِند رسول الله صلى الله عليه وسلم فَجَاءه قَومٌ عُرَاةٌ مُجْتَابِي النِّمَار أَو العَبَاءِ، مُتَقَلِّدِي السُّيُوف، عَامَّتُهُم مِن مُضَر بَل كُلُّهُم مِن مُضَر، فَتَمَعَّر رسول الله صلى الله عليه وسلم لِمَا رَأَى بِهِم مِنَ الفَاقَة، فدَخَل ثُمَّ خَرج، فأَمَر بِلاَلاً فَأَذَّن وَأَقَام، فَصَلَّى ثُمَّ خَطَب، فقال: «(يا أيها الناس اتقوا ربكم الذي خلقكم من نفس واحدة) إلى آخر (إن الله كان عليكم رقيبًا) ، والآية الأخرى التي في آخر الحشر: (يا أيها الذين آمنوا اتقوا الله ولتنظر نفس ما قدمت لغد) تَصَدَّق رَجُلٌ مِن دِينَارِهِ، مِن دِرهَمِهِ، مِن ثَوبِهِ، مِن صَاعِ بُرِّهِ، مِنْ صَاعِ تَمرِهِ -حتَّى قال- وَلَو بِشِقِّ تَمرَة» فَجَاء رَجُلٌ مِنَ الأَنصَار بِصُرَّةٍ كَادَت كَفُّهُ تَعجَزُ عَنْهَا، بل قَد عَجَزَت، ثُمَّ تَتَابَع النَّاسُ حَتَّى رَأَيتُ كَومَين مِن طَعَامٍ وَثِيَابٍ، حَتَّى رَأَيتُ وَجهَ رَسُول الله صلى الله عليه وسلم يَتَهَلَّلُ كَأَنَّه مُذْهَبَة.ٌ فقال رسول الله صلى الله عليه وسلم : «مَنْ سَنَّ فِي الإِسلاَم سُنَّةً حَسَنَةً فَلَهُ أَجْرُهَا، وَأَجْرُ مَنْ عَمِلَ بِهَا بَعْدَهُ، مِنْ غَيرِ أَنْ يَنْقُصَ مِن أُجُورِهِم شَيءٌ، وَمَنْ سَنَّ فِي الإِسلاَم سُنَّةً سَيِّئَةً كَانَ عَلَيه وِزْرُهَا، وَوِزرُ مَنْ عَمِلَ بِهَا مِنْ بعدِه، من غير أن ينقُص مِن أَوزَارِهَم شيء».","en":"Jābir ibn ‘Abdullāh (may Allah be pleased with him) reported: We were with Messenger of Allah (may Allah's peace and blessings be upon him) shortly after dawn when there came to him some people clad in woolen rags, or covered with sleeveless blankets; and with swords hanging down from their necks. Most of them, rather all of them, belonged to the Mudar tribe. The Prophet's face changed when he saw them starving. Then he went into his house and came out; then he commanded Bilāl to proclaim the Adhān. So he proclaimed the Adhān and recited Iqāmah and the Prophet led the prayer. Then he delivered a sermon saying: (O mankind, fear your Lord, who created you from one soul and created from it its mate and dispersed from both of them many men and women. And fear Allah, through whom you ask one another, and the wombs. Indeed Allah is ever, over you, an Observer) [Sūrat An-Nisā':1]. He also recited a verse at the end of Sūrat al-Hashr: (O you who believe, fear Allah and keep your duty to Him. And let every one look what he has sent forth for the tomorrow.) Thereafter, every man gave in charity dinar, dirham, clothes, measure-fulls of wheat and measure-fulls of dates till he said: \"(Give in charity) be it half a date.\" Then a man from the Ansār came with a bag which was difficult for him to hold in his hand. Thereafter, the people came successively (with charity) till I saw two heaps of food and clothes. I noticed that the Messenger's face was glowing like that of the bright moon or glittering gold. Then he said: \"Whosoever introduces a good practice in Islam, there is for him its reward and the reward of those who act upon it after him without anything being diminished from their rewards. And whosoever introduces an evil practice in Islam will shoulder its sin and the sins of all those who will act upon it, without diminishing in any way their burden.\"","ur":"جریر بن عبد اللہ رضی اللہ عنہ بیان کرتے ہیں کہ ہم دن کے آغاز میں رسولﷺکے پاس تھے کہ آپﷺکے پاس کچھ ایسے لوگ آئے، جو ننگے بدن تھے، وہ اون کی دھاری دار چادریں یا کمبل ڈالے ہوئے اور گردنوں میں تلوار لٹکائے ہوئے تھے۔ ان کی اکثریت مضر قبیلے سے بلکہ سارے ہی مضر سے تھے۔ جب رسول اللہﷺنے ان کی فاقہ زدگی کا مشاہدہ فرمایا، تو آپ کا چہرہ متغیر ہو گیا۔ آپ (گھر) کے اندر تشریف لے گئے اور باہر آگئے۔ پھر بلال رضی اللہ عنہ کو حکم دیا، انھوں نے اذان دی، (پھر جب لوگ نماز کے لیے جمع ہوگئے تو) تکبیر کہی اور آپﷺنے نماز پڑھائی۔ اس کے بعد لوگوں سے خطاب کرتے ہوئے فرمایا: (لوگو! اپنے اس رب سے ڈرو، جس نے تمھیں ایک جان سے پیدا فرمایا) یہاں سے (یقینا اللہ تمھاری خبر نگہبانی کرنے والا ہے۔)تک۔ (سورۂ نساء:۱) اس کے بعد سورۂ حشر کی آخری آیت پڑھی۔( اے ایمان والو ! اللہ سے ڈرو اور ہر نفس کو چاہیے کہ اس نے کل(قیامت) کے لیے جو آگے بھیجا ہے، اسے دیکھے)۔ ( اس کےبعد آپ نے صدقہ و خیرات کی ترغیب دی) فرمایا: ہر آدمی کو چاہیے کہ صدقہ کرے؛ دینار و درہم کا ، کپڑے کا، گندم کے صاع کا ، کھجور کے صاع کا، حتی کہ فرمایا گرچہ کھجور کا ایک ٹکڑا ہی کیوں نہ ہو۔ چنانچہ انصار میں سے ایک آدمی ایک تھیلی لے کر آیا، (جو اتنی بھاری تھی کہ) اس کی ہتھیلی اس کو اٹھانے سے عاجز آر ہی تھی؛ بلکہ عاجز ہو چکی تھی۔ پھر لوگ ( لے لے کر ) پے در پے آتے رہے، یہاں تک کہ میں نے دو ڈھیر دیکھے؛ ایک کھانے کے سامان کا اور دوسرا کپڑوں کا۔ تب میں نے دیکھا کہ رسول اللہﷺکا چہرۂ انور اس طرح چمک رہا تھا، گو یا سونے کا ٹکڑا ہو۔ پھر رسول اللہﷺنے فرمایا: \"جو شخص اسلام میں کوئي اچھا طریقہ جاری کرے گا، اسے اس کا اجر ملے گا اور اس کے بعد اس پر عمل کرنے والے تمام لوگوں کے برابر اجر ملے گا۔ جب کہ عمل کرنے والوں کے اجر میں کوئی کمی نہیں کی جاۓ گی اور جو اسلام میں کوئی بُرا طریقہ جاری کرے گا، اس پر اس کا گناہ ہوگا اور اس کے بعد اس پر عمل کرنے والے تمام لوگوں کے برابر گناہ ہوگا اور عمل کرنے والوں کے گناہ میں کوئی کمی نہیں کی جاۓ گی۔","titleAr":"الْقُدْوَةُ فِي فِعْلِ الْخَيْرِ","titleUr":"نیکی میں قابلِ پیروی مثال قائم کرنا"},{"id":"3395","number":38,"title":"Avoiding excess in religion","section":5,"sectionTitle":"A balanced Prophetic path","slug":"38-avoiding-excess-in-religion","ref":"Sunan Ibn Majah 3029","source":"https://hadeethenc.com/en/browse/hadith/3395","primary":"https://sunnah.com/ibnmajah:3029","ar":"عَنْ ابْنِ عَبَّاسٍ رضي الله عنهما قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ غَدَاةَ الْعَقَبَةِ وَهُوَ عَلَى نَاقَتِهِ: «الْقُطْ لِي حَصًى» فَلَقَطْتُ لَهُ سَبْعَ حَصَيَاتٍ، هُنَّ حَصَى الْخَذْفِ، فَجَعَلَ يَنْفُضُهُنَّ فِي كَفِّهِ وَيَقُولُ: «أَمْثَالَ هَؤُلَاءِ فَارْمُوا» ثُمَّ قَالَ: «أَيُّهَا النَّاسُ، إِيَّاكُمْ وَالْغُلُوَّ فِي الدِّينِ، فَإِنَّما أَهْلَكَ مَنْ كَانَ قَبْلَكُمْ الْغُلُوُّ فِي الدِّينِ».","en":"Ibn ‘Abbās (may Allah be pleased with him and his father) reported: On the morning of ‘Aqabah, when the Messenger of Allah (may Allah's peace and blessings be upon him) was atop his she-camel, he said: \"Pick up some pebbles for me.\" So I picked up seven pebbles for him, which were the size of pebbles used for flinging with fingers. He started shaking them in his hand and saying: \"Throw the like of these.\" Then, he said: \"O people, beware of immoderation in religion, for those before you were doomed because of immoderation in religion.\"","ur":"ابن عباس رضی اللہ عنہما سے مروی ہے، وہ کہتے ہیں: اللہ کے رسول صلی اللہ علیہ وسلم نے عَقَبَہ کی صبح، جب کہ آپ اپنی اونٹنی پر سوار تھے، فرمایا: \"میرے لیے کچھ کنکر چن کر لاؤ۔\" چنانچہ میں نے سات کنکر چن کر پیش کیے، جو چنے کے دانے کے برابر تھے۔ آپ انھیں اپنی ہتھیلی میں رکھ کر جھاڑنے لگے اور کہنے لگے : \"اسی طرح کے کنکر مارا کرو\"۔ پھر فرمایا :  \"لوگو، دین میں غلو سے بچو۔ کیوں کہ دین میں غلو  نے ہی تم سے پہلے کے لوگوں کو ہلاک کیا ہے۔\"","titleAr":"اجْتِنَابُ الْغُلُوِّ فِي الدِّينِ","titleUr":"دین میں غلو سے اجتناب"},{"id":"4801","number":39,"title":"Learning together and helping others","section":5,"sectionTitle":"A balanced Prophetic path","slug":"39-learning-together-and-helping-others","ref":"Sahih Muslim 2699","source":"https://hadeethenc.com/en/browse/hadith/4801","primary":"https://sunnah.com/muslim:2699","ar":"عَنْ أَبِي هُرَيْرَةَ رضي الله عنه قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «مَنْ نَفَّسَ عَنْ مُؤْمِنٍ كُرْبَةً مِنْ كُرَبِ الدُّنْيَا نَفَّسَ اللهُ عَنْهُ كُرْبَةً مِنْ كُرَبِ يَوْمِ الْقِيَامَةِ، وَمَنْ يَسَّرَ عَلَى مُعْسِرٍ يَسَّرَ اللهُ عَلَيْهِ فِي الدُّنْيَا وَالْآخِرَةِ، وَمَنْ سَتَرَ مُسْلِمًا سَتَرَهُ اللهُ فِي الدُّنْيَا وَالْآخِرَةِ، وَاللهُ فِي عَوْنِ الْعَبْدِ مَا كَانَ الْعَبْدُ فِي عَوْنِ أَخِيهِ، وَمَنْ سَلَكَ طَرِيقًا يَلْتَمِسُ فِيهِ عِلْمًا سَهَّلَ اللهُ لَهُ بِهِ طَرِيقًا إِلَى الْجَنَّةِ، وَمَا اجْتَمَعَ قَوْمٌ فِي بَيْتٍ مِنْ بُيُوتِ اللهِ يَتْلُونَ كِتَابَ اللهِ وَيَتَدَارَسُونَهُ بَيْنَهُمْ إِلَّا نَزَلَتْ عَلَيْهِمِ السَّكِينَةُ، وَغَشِيَتْهُمُ الرَّحْمَةُ، وَحَفَّتْهُمُ الْمَلَائِكَةُ، وَذَكَرَهُمُ اللهُ فِيمَنْ عِنْدَهُ، وَمَنْ بَطَّأَ بِهِ عَمَلُهُ لَمْ يُسْرِعْ بِهِ نَسَبُهُ».","en":"Abu Hurayrah (may Allah be pleased with him) reported: The Messenger of Allah (may Allah's peace and blessings be upon him) said: \"Whoever relieves a believer from one of the hardships of this world, Allah will relieve him from one of the hardships of the Day of Judgment. Whoever makes things easy for someone in difficulty, Allah will make things easy for him in this world and the Hereafter. Whoever covers a Muslim, Allah will cover him in this world and the Hereafter. Allah is in the aid of the slave as long as the slave is in the aid of his brother. Whoever treads a path seeking knowledge, Allah will make easy for him a path to Paradise. No group of people gather in one of the houses of Allah, reciting the Book of Allah and studying it among themselves, except that tranquility descends upon them, mercy envelops them, the angels surround them, and Allah mentions them to those near Him. And whoever is slowed down by his deeds will not be hastened forward by his lineage.\"","ur":"ابو ہریرہ رضی اللہ عنہ سے روایت ہے، وہ کہتے ہیں کہ اللہ کے رسول ﷺ نے فرمایا: ”جس نے کسی مومن کی دنیا کی پریشانیوں میں سے کوئی پریشانی دور کردی، اللہ تعالیٰ بروز قیامت اس کی پریشانیوں میں سے ایک پریشانی دور کردے گا۔ جس نے کسی تنگ دست پر آسانی کی، اللہ اس پر دنیا وآخرت میں آسانی کرے گا۔ جس نے کسی مسلمان کی عیب پوشی کی، اللہ تعالیٰ دنیا و آخرت میں اس کی عیب پوشی فرمائے گا۔ اللہ تعالیٰ بندے کی مدد کرتا رہتا ہے جب تک بندہ اپنے بھائی کی مدد کرتا رہتا ہے۔ جو شخص علم کی تلاش میں کسی راستے پر چلا اللہ تعالیٰ اس كی وجہ سے اس کے لیے جنت کی راہ آسان کردیتا ہے۔ جب کوئی قوم اللہ کے کسی گھر میں جمع ہو کر اللہ کی کتاب کی تلاوت کرتی ہے اور اسے آپس میں پڑھتی پڑھاتی ہے، تو ان پر سکینت کا نزول ہوتا ہے، (اللہ تعالیٰ کی) رحمت ان کو ڈھانپ لیتی ہے اور اللہ اپنے پاس موجود فرشتوں میں ان کا ذکر کرتا ہے۔ اور جس کا عمل اسے پیچھے کردے، اس کا نسب اسے آگے نہیں لے جاسکتا۔“","titleAr":"مُدَارَسَةُ الْعِلْمِ وَإِعَانَةُ الْآخَرِينَ","titleUr":"مل کر علم سیکھنا اور دوسروں کی مدد کرنا"},{"id":"66272","number":40,"title":"Sent as a mercy","section":5,"sectionTitle":"A balanced Prophetic path","slug":"40-sent-as-a-mercy","ref":"Sahih Muslim 2599","source":"https://hadeethenc.com/en/browse/hadith/66272","primary":"https://sunnah.com/muslim:2599","ar":"عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قِيلَ: يَا رَسُولَ اللهِ ادْعُ عَلَى المُشْرِكِينَ قَالَ: «إِنِّي لَمْ أُبْعَثْ لَعَّانًا، وَإِنَّمَا بُعِثْتُ رَحْمَةً».","en":"Abu Hurayrah (may Allah be pleased with him) reported: It was said: O Messenger of Allah, supplicate against the polytheists. He said: \"I have not been sent as an invoker of curses; rather, I have been sent as a mercy.\"","ur":"ابوہریرہ رضی اللہ عنہ سے مروی ہے، وہ کہتے ہیں : کہا گیا: اے اللہ کے رسول ﷺ! مشرکوں پر بد دعا کردیں، تو آپ ﷺ نے فرمایا: \"مجھے لعنت کرنے والا بنا کر نہيں بھیجا گیا ہے۔ مجھے تو رحمت بنا کر بھیجا گیا ہے\"۔","titleAr":"بُعِثَ رَحْمَةً","titleUr":"رحمت بنا کر بھیجا گیا"}];